const top_darius = {
  champion: '다리우스',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도를 올려 붙은 뒤 침묵을 걸고, 맞지 않는 동안 (P)\'인내심\'으로 체력을 채워요. 1~2레벨에는 평타와 (W)\'마비의 일격\'으로 (P)\'과다출혈\'을 두세 번만 쌓고 빠져서 출혈이 다 들어가게 하세요. 가렌이 (Q)\'결정타\'로 달려오면 뒤로 물러나 (Q)\'학살\' 바깥 날에 걸리는 거리를 만들어 두는 게 좋아요.', lv3: '(Q)\'결정타\' 침묵에 걸리면 (E)\'포획\'과 (Q)\'학살\'을 쓸 수 없으니, 가렌이 Q를 쓴 직후 빠졌다가 침묵이 풀리는 순간 (E)\'포획\'으로 다시 끌어오세요. (W)\'용기\'를 켠 가렌은 보호막과 강인함을 얻으니, 그 시간에는 바깥 날 (Q)\'학살\'로 회복만 챙기고 길게 붙지 마세요. (P)\'인내심\'은 공격에 맞지 않을 때 체력을 채우니, 짧게라도 자주 평타를 묻혀 회복 틈을 주지 마세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력이 많을수록 강해지니, 내 체력이 낮을 때는 무리하게 버티지 말고 먼저 빠지세요. 반대로 가렌에게 출혈을 가득 쌓았다면 (R)\'녹서스의 단두대\'로 먼저 끝내는 쪽이 안전해요. 가렌은 (Q)\'결정타\' 말고는 거리를 벌릴 수단이 없으니 라인을 당겨 두고 정글러가 오면 (E)\'포획\'으로 끌어와 주세요.', item: '기본값인 요우무의 유령검을 첫 코어로 가면 (Q)\'결정타\'로 도망치는 가렌도 끝까지 따라가 출혈을 이어 붙일 수 있어요. 신발은 평타와 (E)\'심판\' 물리 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'인내심\' 회복을 눌러야 (R)\'녹서스의 단두대\' 처형 타이밍이 빨라져요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기지만 근접 몸싸움은 약한 편이에요. 첫 웨이브부터 앞으로 서서 갱플랭크가 막타를 치러 다가올 때마다 평타를 묻혀 (P)\'과다출혈\'을 쌓으세요. (P)\'불의 심판\'이 붙은 평타를 맞고 오래 붙어 있을 이유는 없으니 출혈만 남기고 빠지는 교환이 좋아요.', lv3: '(W)\'괴혈병 치료\'는 (W)\'마비의 일격\' 둔화 같은 군중 제어를 풀고 체력도 채우니, 이 스킬을 먼저 쓰게 만든 뒤에 길게 싸우세요. 미니언 근처에 깔린 (E)\'화약통\'이 터지면 둔화가 걸리니, 통 위치를 보고 통과 겹치지 않는 각도에서 (E)\'포획\'으로 끌어오세요. 끌어온 뒤 바깥 날 (Q)\'학살\'과 평타로 중첩을 빠르게 채우면 갱플랭크가 버티기 어려워요.', lv6: '갱플랭크가 (R)\'포탄 세례\'를 다른 라인에 쓰면 그 사이 라인을 밀고 포탑을 압박하세요. (P)\'과다출혈\'이 가득 쌓인 갱플랭크는 (R)\'녹서스의 단두대\' 한 번으로 정리되는 경우가 많으니 (W)\'괴혈병 치료\'가 빠졌는지 보고 마무리하세요. 도망치는 길에 (R)\'포탄 세례\'가 깔리면 둔화로 따라가기 어려우니 장판 밖에서 (E)\'포획\' 거리를 노리세요.', item: '요우무의 유령검을 첫 코어로 올려 (Q)\'혀어어어업상\' 사거리에서 견제하는 갱플랭크에게 빠르게 붙으세요. 신발은 평타와 (Q)\'혀어어어업상\' 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\' 회복량을 줄이면 (R)\'녹서스의 단두대\' 처형 각이 훨씬 자주 나와요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화와 견제를 넣고, 스킬을 쓸 때마다 (P)\'서비스 시간\'으로 체력을 회복해요. 술통이 떨어지는 자리를 피해 막타를 받고, 술통이 빠진 순간 다가가 평타로 (P)\'과다출혈\'을 묻히세요. 그라가스는 근접 평타 교환이 강하지 않으니 1~2레벨부터 출혈을 계속 쌓아 회복 효율을 떨어뜨리세요.', lv3: '(E)\'몸통 박치기\' 기절에 맞으면 (Q)\'학살\'을 바깥 날로 맞히기 어려워지니, 그라가스가 E를 쓰기 전에는 너무 깊게 들어가지 마세요. (W)\'취중 분노\'를 켜면 받는 피해가 줄어드니 그 시간에는 (E)\'포획\'을 아껴 두고 끝난 뒤에 끌어와 중첩을 채우세요. E가 빠진 그라가스는 빠질 돌진기가 없어서 (W)\'마비의 일격\' 둔화만으로도 계속 붙어 있을 수 있어요.', lv6: '(R)\'술통 폭발\'은 대상을 밀어내니, 출혈을 쌓던 중에 밀려나면 처형 각이 끊길 수 있어요. 그라가스가 (R)\'술통 폭발\'을 쓴 뒤에 (E)\'포획\'으로 다시 끌어와 (R)\'녹서스의 단두대\'를 노리세요. 라인을 밀어 두면 그라가스가 정글러와 함께 나를 적 정글 쪽으로 날리는 각이 생기니 시야 없이 깊게 서지 마세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'몸통 박치기\'로 빠지는 그라가스를 이동 속도로 따라잡으세요. 신발은 마법 피해와 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\' 회복이 계속 들어가니 점화로 끊어 줘야 처형이 깔끔해요.' },
    '그웬': { lv1: '그웬은 평타마다 (P)\'가위 난도질\' 추가 피해와 회복이 붙어서, 1~2레벨에도 근접 평타 교환을 오래 하면 회복량이 쌓여요. 첫 웨이브에는 그웬이 막타를 치러 올 때 평타와 (W)\'마비의 일격\'으로 출혈만 남기고 빠지세요. 그웬이 (Q)\'싹둑싹둑!\'을 모아 들어오면 바깥 날 (Q)\'학살\'로 회복을 챙기며 맞받으세요.', lv3: '(W)\'신성한 안개\' 밖에서는 그웬을 대상으로 지정할 수 없지만 (E)\'포획\'과 (Q)\'학살\'은 범위 스킬이라 그대로 맞아요. 안개를 켜면 평타 대신 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히세요. (E)\'돌격가위\'로 거리를 벌리며 평타를 치려 할 때 (W)\'마비의 일격\' 둔화로 다시 붙으세요.', lv6: '(R)\'바느질\'은 바늘을 여러 번 던지며 둔화를 거니, 그웬이 궁극기를 다 쓰기 전에 (E)\'포획\'으로 끌어와 근접 거리로 만들어야 해요. (R)\'녹서스의 단두대\'는 대상 지정이라 (W)\'신성한 안개\' 안의 그웬에게는 안개 안으로 들어가서 써야 해요. 중첩을 가득 쌓아 처치하면 (R)\'녹서스의 단두대\'가 초기화되니, 상대 정글러가 합류한 싸움에서도 다음 대상을 이어서 노리세요.', item: '요우무의 유령검과 함께 처형인의 대검을 일찍 사서 (P)\'가위 난도질\' 회복을 줄이세요. 신발은 그웬의 마법 피해를 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 회복을 줄여야 그웬이 오래 버티지 못해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 멀리서 견제하고 둔화를 걸며, 돌아오는 부메랑을 받으면 다시 빨리 던져요. 부메랑 직선을 피하면서 미니언 웨이브 가까이 서고, 나르가 막타를 치러 다가오면 평타로 (P)\'과다출혈\'을 묻히세요. (E)\'폴짝\'으로 빠지는 나르를 무리하게 쫓기보다 출혈 피해가 들어가게 두는 편이 좋아요.', lv3: '작은 나르는 (E)\'포획\'에 걸리면 (E)\'폴짝\' 말고는 빠질 수단이 없으니, 폴짝이 빠진 것을 확인하고 끌어오세요. 분노가 차오르면 메가 나르가 되어 (W)\'쿵쾅\'으로 기절을 걸 수 있으니, 분노가 거의 찼을 때는 교환을 멈추고 변신이 끝날 때까지 거리를 두세요. 작은 나르일 때 (Q)\'학살\' 바깥 날을 맞혀 체력 차이를 벌려 두는 게 핵심이에요.', lv6: '메가 나르의 (R)\'나르!\'는 벽 근처에서 맞으면 기절까지 걸리니, 벽을 등지고 싸우지 마세요. 변신이 끝난 작은 나르는 몸이 약해서 (P)\'과다출혈\'이 가득 쌓이면 (R)\'녹서스의 단두대\'로 끝낼 수 있어요. 나르는 갱킹을 돕는 능력이 좋으니 라인을 밀었을 때 강가 쪽 시야를 꼭 확인하세요.', item: '요우무의 유령검으로 (Q)\'부메랑 던지기\' 견제 뒤 거리를 벌리는 나르를 따라가세요. 신발은 평타와 부메랑 물리 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'폴짝\' 이후 거리를 다시 좁혀야 출혈을 이어 갈 수 있어요.' },
    '나서스': { lv1: '나서스는 초반에 (Q)\'흡수의 일격\'으로 미니언을 잡아 중첩을 쌓는 데 집중해서 1~2레벨 몸싸움이 약해요. 나서스가 (Q)\'흡수의 일격\'으로 막타를 치러 올 때마다 평타와 (W)\'마비의 일격\'을 묻혀, 막타 하나에 출혈 피해를 계속 치르게 하세요. 웨이브를 상대 포탑 쪽으로 밀어 두면 나서스가 막타를 놓치며 성장이 늦어져요.', lv3: '(W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 같이 떨어지니, 나서스가 W를 쓴 직후에는 무리하게 평타 싸움을 하지 말고 (Q)\'학살\' 바깥 날로 회복을 챙기세요. (E)\'영혼의 불길\'은 방어력을 낮추니 장판 위에서 오래 버티지 마세요. W가 빠진 나서스는 (E)\'포획\'으로 끌어온 뒤 출혈 중첩을 빠르게 채우면 버티지 못해요.', lv6: '(R)\'사막의 분노\'를 켠 나서스는 체력과 공격 범위가 늘어나니, 궁극기 지속시간 동안은 길게 싸우지 말고 (W)\'마비의 일격\' 둔화를 건 뒤 거리를 벌려 시간을 버세요. 궁극기가 끝난 뒤에 (P)\'과다출혈\'을 가득 쌓고 (R)\'녹서스의 단두대\'로 마무리하는 게 안정적이에요. 나서스는 시간이 지날수록 강해지니 라인을 꾸준히 밀어 포탑 골드를 먼저 챙기세요.', item: '나서스는 방어력이 높아지고 (P)\'영혼의 포식자\'로 회복하니 칠흑의 양날 도끼를 첫 코어로 가고 처형인의 대검을 함께 맞추세요. 신발은 평타와 (Q)\'흡수의 일격\' 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 초반 킬각을 만들어 나서스의 중첩 성장을 늦추세요.' },
    '녹턴': { lv1: '(Q)\'황혼의 인도자\' 사거리를 확인하며 미니언을 챙기고 적의 견제를 받아내세요. (Q)\'학살\'의 도끼날을 맞혀 체력을 회복하면서 (P)\'과다출혈\' 중첩을 쌓을 준비를 해요.', lv3: '(W)\'어둠의 장막\'은 적의 다음 스킬을 막아주니 (E)\'포획\'을 먼저 쓰지 말고 장막이 사라진 뒤에 쓰세요. 장막이 사라지면 (E)\'포획\'으로 끌어당기고 (W)\'마비의 일격\'과 (Q)\'학살\'로 (P)\'과다출혈\' 중첩을 쌓아요. (E)\'말할 수 없는 공포\'는 사거리 밖으로 벗어나 연결을 끊지 못하면 공포에 빠지니, 체력 여유가 없다면 미리 뒤로 빠져 연결을 끊으세요.', lv6: '녹턴이 (R)\'피해망상\'으로 돌격해 오면 붙은 뒤 (Q)\'학살\' 도끼날과 (W)\'마비의 일격\'으로 (P)\'과다출혈\' 중첩을 쌓으세요. (W)\'어둠의 장막\'은 (R)\'녹서스의 단두대\'도 막을 수 있으니 장막이 빠진 것을 보고 궁극기를 쓰세요. (R)\'피해망상\' 중에는 시야가 줄어 정글러 위치를 알기 어려우니 라인을 너무 밀지 마세요.', item: '판금 장화와 굶주린 히드라를 선택해요. 기본 공격 피해를 줄이고 (Q)\'학살\'과 함께 생명력 흡수를 통해 라인 유지력을 높여요.', spell: '점멸과 점화. 적의 체력을 낮춰 (R)\'녹서스의 단두대\'로 처치하기 쉽게 만들고 체력 회복 효과를 줄여요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'로 멀리서 견제하지만 1~2레벨에는 스킬이 적어서 근접 압박을 버티기 어려워요. 막타를 치러 오는 라이즈에게 평타를 묻혀 (P)\'과다출혈\'을 쌓고, (Q)\'과부하\' 직선은 미니언 뒤에서 피하세요. 마나 소모가 큰 라이즈는 초반에 체력을 깎이면 라인을 지키기 힘들어요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'을 맞으면 속박되니, 라이즈가 E를 맞힌 직후에는 (E)\'포획\' 거리로 들어가지 마세요. 반대로 (W)\'룬 감옥\'이 빠졌다면 라이즈는 묶을 수단이 없으니 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날까지 이어 가세요. 붙어서 (W)\'마비의 일격\'으로 둔화를 걸면 라이즈가 거리를 다시 벌리기 어려워요.', lv6: '(R)\'공간 왜곡\'은 이동용 궁극기라 라이즈가 라인을 비우는 경우가 많으니, 사라지면 라인을 밀고 포탑을 공격하세요. 라이즈는 체력이 낮아 (P)\'과다출혈\' 중첩만 쌓이면 (R)\'녹서스의 단두대\' 각이 쉽게 나와요. 다만 속박 연계에 묶인 채 정글러에게 잡히지 않도록 라인을 너무 깊게 밀지 마세요.', item: '요우무의 유령검의 이동 속도로 (Q)\'과부하\' 사거리 밖으로 빠지는 라이즈를 따라가세요. 신발은 마법 피해와 속박 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 라이즈가 버티기 전에 초반 킬로 성장을 늦추는 데 점화가 도움이 돼요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 미니언과 나를 같이 태우며 근접 거리에서 강한 견제를 넣어요. (Q)\'화염방사기\' 범위 밖으로 비켜서서 막타를 챙기고, 럼블이 Q를 다 쓴 뒤에 평타와 (W)\'마비의 일격\'으로 출혈을 묻히세요. 열기가 차서 과열되면 럼블은 스킬을 못 쓰니 그때 바로 붙으세요.', lv3: '(W)\'고철 방패\'가 켜지면 출혈 피해가 방패에 먼저 들어가니, 방패가 빠지는 것을 보고 (E)\'포획\'으로 끌어오세요. (E)\'전기 작살\'에 맞으면 느려지고 마법 저항력도 줄어드니 작살 두 개를 다 맞은 상태에서 깊게 따라가지 마세요. 끌어온 럼블에게 바깥 날 (Q)\'학살\'을 맞히면 회복까지 챙기며 길게 싸울 수 있어요.', lv6: '이번 패치에 (R)\'이퀄라이저 미사일\' 피해가 올랐으니, 궁극기 장판 위에서 싸우지 말고 바로 빠져나오세요. 럼블이 궁극기를 쓴 뒤 장판 밖으로 끌어내 (P)\'과다출혈\'을 쌓으면 (R)\'녹서스의 단두대\'를 노릴 수 있어요. 럼블 궁극기는 정글 갱킹과 잘 맞으니 라인을 밀었을 때 정글러 위치를 꼭 확인하세요.', item: '요우무의 유령검을 첫 코어로 가면 (W)\'고철 방패\'로 빠지는 럼블을 쫓을 수 있어요. 신발은 화염과 미사일 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해야 (W)\'고철 방패\'로 버티는 럼블을 잡을 수 있어요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해와 회복을 같이 챙기며 초반 몸싸움이 강해요. 1~2레벨에는 레넥톤의 Q 범위를 피해서 막타를 받고, 레넥톤이 Q를 쓴 뒤에 평타로 (P)\'과다출혈\'을 묻히세요. 분노가 쌓인 레넥톤과 정면으로 붙기보다 출혈을 남기고 빠지는 교환을 반복하세요.', lv3: '분노가 높을 때 (W)\'무자비한 포식자\'를 맞으면 기절이 길어지니, 레넥톤의 분노 게이지를 보고 높을 때는 (E)\'포획\'을 아껴 두세요. (E)\'자르고 토막내기\'로 들어와 빠지는 레넥톤에게는 들어오는 순간 (Q)\'학살\' 바깥 날을 맞히면 회복으로 피해를 되돌릴 수 있어요. 분노가 낮을 때 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\'까지 이으면 레넥톤이 도망치기 어려워요.', lv6: '(R)\'강신\'을 쓴 레넥톤은 체력이 늘고 분노가 계속 차니, 궁극기 시간 동안은 거리를 벌리고 지속시간이 끝나길 기다리세요. (R)\'강신\'이 끝나면 레넥톤의 추가 체력이 사라지니, 그때 (E)\'포획\'으로 다시 끌어와 출혈을 쌓고 (R)\'녹서스의 단두대\'를 노리세요. 레넥톤은 (E)\'자르고 토막내기\'를 두 번 써서 빠져나가니 (E)\'포획\'은 이 돌진이 다 빠진 뒤에 쓰세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'자르고 토막내기\'로 빠지는 레넥톤을 따라가세요. 신발은 레넥톤의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'양떼 도륙\' 회복량을 깎아야 싸움이 길어질 때 이길 수 있어요.' },
    '렝가': { lv1: '렝가는 수풀에서 기본 공격을 하면 (P)\'보이지 않는 포식자\'로 대상에게 도약하니 수풀 근처에서는 거리를 유지하세요. (Q)\'학살\'의 도끼날로 챔피언을 맞혀 체력을 회복하며 미니언과 함께 적을 견제하세요.', lv3: '렝가가 (E)\'올가미 투척\'을 먼저 사용한다면 (E)\'포획\'으로 끌어당겨 딜교환을 시작하세요. (W)\'마비의 일격\'으로 이동 속도를 줄인 뒤 (P)\'과다출혈\' 중첩을 쌓으며 싸워요.', lv6: '렝가가 (R)\'사냥의 전율\'로 도약해 오면 내 방어력이 잠시 감소하니 바로 맞서기보다 (Q)\'학살\' 도끼날로 체력을 회복하며 버티세요. 렝가의 강화된 (W)\'전투의 포효\'는 군중 제어를 해제하니 (E)\'포획\'은 그 포효를 쓴 뒤에 맞혀 (P)\'과다출혈\' 중첩을 쌓고 (R)\'녹서스의 단두대\'로 마무리하세요. 라인을 관리하며 정글러의 개입에 대비해요.', item: '판금 장화와 발걸음 분쇄기를 구매하세요. 렝가의 기본 공격 피해를 줄이고 쪼개기 효과로 전투를 진행해요.', spell: '점멸과 점화. 렝가의 (W)\'전투의 포효\'를 통한 회복을 억제하고 킬을 노리기 좋아요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'와 (E)\'용맹\'으로 들어와 짧게 때리고 빠지는 교환이 강해요. 1~2레벨에는 리븐이 들어오는 순간 평타를 맞받아 (P)\'과다출혈\'을 묻히고, 리븐이 빠지면 쫓지 말고 출혈 피해가 들어가게 두세요. 리븐은 기력이 없어 스킬을 자주 쓰니 스킬이 빠진 뒤에 압박하는 게 좋아요.', lv3: '(W)\'기 폭발\' 기절을 맞으면 (Q)\'학살\'을 바깥 날로 맞히기 어려우니, 리븐이 W를 쓴 뒤에 (Q)\'학살\'을 쓰세요. (Q)\'부러진 날개\' 세 번째 타격은 밀쳐내니 그 뒤에 (E)\'포획\'으로 다시 끌어오면 리븐이 빠질 수단이 줄어요. (E)\'용맹\'으로 피해를 흡수하는 동안 (Q)\'학살\'을 쓰면 아까우니, 흡수가 끝나는 시점에 바깥 날을 맞추세요.', lv6: '(R)\'추방자의 검\'을 켠 리븐은 한 번 쓸 수 있는 원거리 베기로 마무리를 노리니, 체력이 낮을 때는 그 사거리 밖으로 빠지세요. 리븐이 궁극기를 쓴 뒤 출혈 중첩을 가득 쌓아 (R)\'녹서스의 단두대\'로 끊으면 리븐의 마무리 각보다 먼저 정리할 수 있어요. 리븐은 (Q)\'부러진 날개\'와 (E)\'용맹\'으로 벽을 넘어 도망칠 수 있으니 무리하게 쫓지 마세요.', item: '요우무의 유령검을 첫 코어로 가면 (Q)\'부러진 날개\'로 들어왔다 빠지는 리븐을 따라갈 수 있어요. 신발은 리븐의 물리 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 마무리를 더해야 리븐이 빠져나가기 전에 처치할 수 있어요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 멀리서 견제하며 둔화를 걸어 근접 챔피언의 접근을 막아요. (Q)\'얼음 파편\'은 맞은 대상을 꿰뚫고 뒤로 퍼지니 미니언 바로 뒤에 서지 말고, 리산드라가 막타를 치러 다가오면 평타로 (P)\'과다출혈\'을 묻히세요. 1~2레벨에는 리산드라의 스킬이 적으니 이때 체력 차이를 벌려 두세요.', lv3: '(W)\'서릿발\'에 묶이면 (Q)\'학살\'을 바깥 날로 맞히기 어려우니, 리산드라가 W를 쓴 뒤에 (E)\'포획\'으로 끌어오세요. (E)\'얼음갈퀴 길\'로 순간이동하며 빠지는 리산드라는 E를 쓴 뒤에 쫓으면 거리를 좁히기 쉬워요. 끌어온 리산드라에게 (W)\'마비의 일격\' 둔화를 걸면 다시 빠지기 어려워요.', lv6: '(R)\'얼음 무덤\'을 자신에게 쓰면 무적 상태가 되니, 출혈을 쌓은 리산드라가 궁극기를 쓰면 (R)\'녹서스의 단두대\'를 아껴 두고 무적이 끝난 순간 쓰세요. 리산드라가 나에게 (R)\'얼음 무덤\'을 쓰면 기절한 동안 상대 정글러가 합류하기 쉬우니 시야를 확인하세요. 리산드라는 몸이 약해 출혈 중첩만 쌓이면 (R)\'녹서스의 단두대\' 한 번으로 끝나는 경우가 많아요.', item: '요우무의 유령검의 이동 속도로 (E)\'얼음갈퀴 길\' 순간이동 뒤에도 거리를 다시 좁히세요. 신발은 (W)\'서릿발\' 속박과 (R)\'얼음 무덤\' 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'얼음 무덤\' 회복을 줄이면 무적이 끝난 뒤 마무리가 쉬워요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'과 (E)\'우주류 검술\'로 평타 피해가 강하지만 1~2레벨에는 몸이 약해요. 첫 웨이브부터 앞으로 서서 막타를 치러 오는 마스터 이에게 평타와 (W)\'마비의 일격\'으로 (P)\'과다출혈\'을 쌓으세요. (W)\'명상\'으로 체력을 회복하려 하면 출혈 피해를 계속 넣으며 웨이브를 밀어 두세요.', lv3: '(Q)\'일격 필살\' 중에는 마스터 이를 대상으로 지정할 수 없으니, 마스터 이가 Q로 들어오면 (E)\'포획\'을 아껴 두고 착지한 뒤에 쓰세요. (W)\'명상\'을 쓰는 동안은 받는 피해가 줄어드니 그때는 (Q)\'학살\' 바깥 날을 맞히며 회복만 챙기세요. Q가 빠진 마스터 이를 (E)\'포획\'으로 끌어오면 도망칠 수단이 없어요.', lv6: '(R)\'최후의 전사\'를 쓴 마스터 이는 둔화에 면역이라 (W)\'마비의 일격\' 둔화가 통하지 않으니, 이때는 (E)\'포획\'과 (Q)\'학살\'로 승부하세요. 출혈을 가득 쌓은 마스터 이에게 (R)\'녹서스의 단두대\'를 쓸 때는 (Q)\'일격 필살\'에 피해지지 않도록 Q가 빠졌을 때 쓰세요. 마스터 이를 처치하면 (R)\'녹서스의 단두대\'가 초기화되니 정글러 합류 때 연속 처치를 노리세요.', item: '요우무의 유령검을 첫 코어로 가서 (R)\'최후의 전사\'로 빠르게 움직이는 마스터 이를 따라가세요. 신발은 평타 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'명상\' 회복량을 줄여야 마스터 이를 확실히 잡을 수 있어요.' },
    '마오카이': { lv1: '마오카이는 (P)\'마법 흡수\'로 평타 회복을 챙기며 (Q)\'덤불 주먹\'으로 밀어내고 둔화를 걸어요. 1~2레벨에는 마오카이가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, 이번 패치에 Q 피해가 올랐으니 (Q)\'덤불 주먹\'을 맞지 않는 거리에서 막타를 받으세요. (P)\'마법 흡수\' 회복은 스킬을 맞을수록 자주 돌아오니, 짧게 여러 번보다 한 번에 출혈을 몰아 쌓는 교환을 하세요.', lv3: '(W)\'뒤틀린 전진\' 중에는 마오카이를 대상으로 지정할 수 없고 속박 중에는 걸어서 거리를 맞출 수 없으니, 속박이 풀린 뒤 반 걸음 물러나 (Q)\'학살\' 바깥 날 거리를 다시 잡으세요. (Q)\'덤불 주먹\'으로 밀려난 뒤에는 (E)\'포획\'으로 다시 끌어오면 중첩을 이어 쌓을 수 있어요. (E)\'묘목 던지기\'가 깔린 수풀 근처에서는 싸우지 마세요.', lv6: '(R)\'대자연의 마수\'는 천천히 다가오며 속박하니, 벽이 다가오는 방향을 보고 옆으로 빠져나가세요. 마오카이는 단단해서 처치가 오래 걸리니 출혈 중첩을 가득 유지하며 (R)\'녹서스의 단두대\'를 체력이 충분히 깎인 뒤에 쓰세요. 마오카이가 궁극기를 다른 라인 지원에 쓰면 그 틈에 웨이브를 크게 밀어 포탑을 두드리세요.', item: '단단한 마오카이에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (Q)\'덤불 주먹\' 마법 피해와 속박 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이는 처치가 어려우니 순간이동으로 라인 손해를 줄이며 성장에 집중하세요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄고 군중 제어에 면역이 되니, 먼저 평타를 맞혀 (P)\'공허 태세\'를 벗겨야 해요. (Q)\'공허의 부름\'은 침묵을 거니 피해서 막타를 받고, 말자하가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히세요. 1~2레벨에는 말자하가 근접 공격을 버티기 힘드니 꾸준히 압박하세요.', lv3: '(W)\'공허의 무리\' 공허충이 나를 따라다니면 평타 교환이 손해가 되니, (Q)\'학살\' 바깥 날로 공허충과 말자하를 같이 맞히세요. (P)\'공허 태세\'가 깨진 상태에서 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 걸면 말자하가 도망칠 수단이 없어요. (E)\'재앙의 환상\'에 걸리면 피해가 계속 들어오니 무리하게 오래 싸우지 마세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 상대 정글러가 근처에 있을 때 맞으면 그대로 잡히니 시야를 확인하세요. 말자하는 탈출기가 없어서 출혈 중첩을 가득 쌓으면 (R)\'녹서스의 단두대\'로 쉽게 끊을 수 있어요. 말자하가 라인을 빨리 밀면 포탑 뒤에서 막타를 챙기며 (E)\'포획\' 각을 기다리세요.', item: '요우무의 유령검을 첫 코어로 가면 (Q)\'공허의 부름\' 사거리 밖에서 빠르게 거리를 좁힐 수 있어요. 신발은 마법 피해와 (Q)\'공허의 부름\' 침묵 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 정화로는 (R)\'황천의 손아귀\' 제압을 풀 수 없으니, 말자하 궁극기가 남아 있을 때는 무리하게 깊이 들어가지 마세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 처음 받는 피해를 막고 (Q)\'지진의 파편\'으로 견제하며 이동 속도를 훔쳐요. 평타로 방패를 먼저 벗긴 뒤 (W)\'마비의 일격\'으로 출혈을 묻히고, 파편이 빠진 뒤에 붙으세요. 1~2레벨 말파이트는 (W)\'천둥소리\'가 없으면 평타 교환이 약하니, 방패가 다시 생기기 전에 연달아 붙어 웨이브를 상대 포탑까지 밀어 넣으세요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 떨어지니, 말파이트가 E를 쓴 뒤에 평타 교환보다 (Q)\'학살\' 바깥 날로 피해를 넣으세요. (W)\'천둥소리\'로 평타를 강화한 말파이트와 오래 붙어 있지 말고, 방패가 다시 생기기 전에 (E)\'포획\'으로 끌어와 출혈을 이어 쌓으세요. 말파이트는 방어력이 높으니 (E)\'포획\'의 방어력 무시 효과를 살리세요.', lv6: '(R)\'멈출 수 없는 힘\'은 멀리서 돌진해 공중에 띄우니, 정글러가 근처에 있을 때 궁극기를 맞으면 그대로 잡혀요. (R)\'멈출 수 없는 힘\'을 써 버린 말파이트는 도망칠 길이 (Q)\'지진의 파편\' 이동 속도 훔치기뿐이니, (W)\'마비의 일격\' 둔화로 붙어서 중첩을 끝까지 채우세요. 궁극기가 빠진 말파이트는 다른 라인에 개입할 힘이 없으니 그 틈에 웨이브를 밀어 첫 포탑 골드를 노리세요.', item: '단단한 말파이트에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (Q)\'지진의 파편\'과 (E)\'지면 강타\' 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초반 킬각을 만들어 말파이트의 성장을 늦추세요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'로 미니언과 나를 같이 때리며 1~2레벨부터 피해가 강해요. (Q)\'말살\'은 단일 대상에게 더 강하니 미니언 웨이브 근처에 서서 막타를 받고, 모데카이저가 Q를 쓴 뒤에 평타로 (P)\'과다출혈\'을 묻히세요. (P)\'암흑 탄생\'이 켜지면 주변 피해가 커지니 오래 붙어 있지 마세요.', lv3: '(W)\'불멸\' 보호막은 출혈 피해를 먼저 막으니, 모데카이저가 W를 쓴 뒤에 (E)\'포획\'으로 끌어와 중첩을 쌓으세요. (E)\'죽음의 손아귀\'에 끌려오면 바깥 날 (Q)\'학살\' 거리가 사라지니 E 범위를 피하는 게 먼저예요. E가 빠진 모데카이저는 거리를 좁힐 수단이 없으니 (W)\'마비의 일격\'으로 계속 둔화를 거세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 정글러의 도움도 받을 수 없고 빠져나올 수도 없으니, 끌려가기 전에 출혈을 쌓아 두면 그 안에서 싸우기 쉬워요. 모데카이저는 능력치를 훔쳐가니 체력이 낮을 때는 궁극기가 나오기 전에 빠지세요. (R)\'죽음의 세계\' 안에서 출혈을 가득 채워 (R)\'녹서스의 단두대\'로 처치하면 능력치를 빼앗긴 싸움을 바로 끝낼 수 있어요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'죽음의 손아귀\' 사거리 밖으로 빠르게 움직이세요. 신발은 모데카이저의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'불멸\' 회복을 줄여야 (R)\'죽음의 세계\' 싸움에서 이길 수 있어요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 멀리서 체력 비례 피해를 넣고 둔화를 걸어요. 뼈톱 직선을 미니언 뒤에서 피하면서, 문도가 막타를 치러 다가오면 평타와 (W)\'마비의 일격\'으로 (P)\'과다출혈\'을 묻히세요. 문도는 체력 재생이 강하니 출혈을 쉬지 않고 이어 붙여 회복할 시간을 주지 마세요.', lv3: '(W)\'심장 전기 충격\'은 받은 피해 일부를 저장했다가 회복하니, 문도가 W를 켠 채 들어오면 짧게 맞받고 빠지세요. (E)\'둔기에 의한 외상\'은 잃은 체력에 비례해 강해지니 문도 체력이 낮을 때 평타 교환을 오래 하지 마세요. (E)\'포획\'으로 끌어온 뒤 (Q)\'학살\' 바깥 날을 맞히면 내 회복으로 문도의 지속 피해를 받아낼 수 있어요.', lv6: '(R)\'최대 투여량\'을 쓴 문도는 체력을 크게 회복하고 이동 속도도 빨라지니, 궁극기가 빠진 것을 확인하고 (R)\'녹서스의 단두대\'를 노리세요. 출혈 중첩을 가득 쌓아 두면 궁극기 회복 중에도 처형 피해가 크게 들어가요. (P)\'가고 싶은 데로 간다\'가 처음 맞는 이동 불가 효과를 버티니, 정글러와 함께 노릴 때는 첫 묶는 스킬이 막힐 수 있다는 걸 생각하고 군중 제어를 나눠 쓰세요.', item: '체력이 높고 회복이 많은 문도에게는 칠흑의 양날 도끼를 첫 코어로 가고 처형인의 대검을 함께 맞추세요. 신발은 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\' 마법 피해를 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'최대 투여량\' 회복을 줄여야 문도를 처치할 수 있어요.' },
    '바루스': { lv1: '바루스는 원거리에서 (Q)\'꿰뚫는 화살\'로 견제하고, 평타에 (W)\'역병 화살\'을 쌓아 스킬로 터뜨려요. 바루스가 Q를 충전하느라 움직임이 느려지는 순간 앞으로 압박해 평타로 (P)\'과다출혈\'을 묻히세요. 견제를 맞았다면 무리하게 버티지 말고 웨이브를 받으며 거리를 좁힐 타이밍을 기다리세요.', lv3: '(E)\'퍼붓는 화살\' 위에서는 체력 회복이 줄어드니, (Q)\'학살\' 바깥 날 회복을 기대하고 장판 위에서 싸우지 마세요. 바루스가 E를 쓴 뒤 (E)\'포획\'으로 끌어오면 바루스는 도망칠 수단이 거의 없어요. 끌어온 뒤 (W)\'마비의 일격\' 둔화를 걸면 출혈 중첩을 가득 채울 때까지 붙어 있을 수 있어요.', lv6: '(R)\'부패의 사슬\'은 처음 맞은 대상의 이동을 막으니, 바루스에게 들어가려 할 때 궁극기를 맞으면 그 자리에서 견제를 다 받아요. 바루스가 궁극기를 쓴 뒤에 들어가거나 정글러와 함께 들어가세요. 체력이 낮은 바루스는 (R)\'녹서스의 단두대\' 한 번으로 끝나는 경우가 많아요.', item: '요우무의 유령검의 이동 속도로 원거리 바루스에게 붙으세요. 신발은 평타와 화살 물리 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 견제 거리를 빠르게 좁혀야 바루스를 잡을 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 세 번째 공격마다 고정 피해를 넣고 (Q)\'구르기\'로 거리를 조절해요. 1~2레벨에는 막타를 치러 다가오는 베인에게 평타를 묻혀 (P)\'과다출혈\'을 쌓으세요. 베인은 원거리지만 몸이 약하니 웨이브 근처에 서서 압박하세요.', lv3: '베인과 싸울 때는 라인 옆 벽에서 멀리 떨어져 서야 (E)\'선고\'를 맞아도 기절 없이 밀려나기만 해요. 베인이 (Q)\'구르기\'를 쓴 직후에는 거리를 다시 벌리기 어려우니 그때 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요. 끌려온 베인이 (Q)\'구르기\'로 다시 빠지기 전에 바로 (Q)\'학살\'을 휘둘러 바깥 날을 맞히세요.', lv6: '(R)\'결전의 시간\'을 쓴 베인은 (Q)\'구르기\'로 투명 상태가 되니, 투명해진 베인에게는 (R)\'녹서스의 단두대\'를 쓸 수 없어요. 출혈 중첩을 가득 쌓아 두고 베인이 다시 보이는 순간 (R)\'녹서스의 단두대\'로 끝내세요. 베인이 (Q)\'구르기\'를 빼 버린 순간은 다시 투명해질 수단이 없으니 그때 (E)\'포획\'을 던지세요.', item: '요우무의 유령검으로 (Q)\'구르기\' 이후 거리를 벌리는 베인을 따라가세요. 신발은 평타 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'구르기\'와 (E)\'선고\'로 벌어진 거리를 빠르게 좁혀야 베인을 잡을 수 있어요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 이동 속도를 올려 들어와 기절을 걸고 (W)\'광란의 상처\'로 피해와 회복을 챙겨요. 1~2레벨에는 볼리베어가 Q로 달려오면 뒤로 물러나 (Q)\'학살\' 바깥 날 거리를 만들고, 기절을 맞았다면 평타로 (P)\'과다출혈\'을 맞받으세요. 볼리베어는 초반 평타 교환이 강하니 출혈을 남기고 빠지는 교환을 반복하세요.', lv3: '(W)\'광란의 상처\'를 두 번 맞으면 볼리베어가 회복하니, W 표식이 남은 상태에서는 오래 붙어 있지 마세요. (E)\'천공 분열\' 범위 안에서 볼리베어가 보호막을 얻으니 E가 떨어지는 자리 밖에서 (E)\'포획\'으로 끌어오세요. Q가 빠진 볼리베어는 거리를 좁힐 수단이 없으니 (W)\'마비의 일격\' 둔화로 계속 따라가세요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 다이브할 수 있으니, 체력이 낮을 때는 포탑 뒤라고 안심하지 마세요. 다이브가 끝난 볼리베어는 (Q)\'번개 강타\'가 빠져 있는 경우가 많으니, 포탑 아래에서 (E)\'포획\'으로 끌어와 출혈을 채우고 (R)\'녹서스의 단두대\'로 돌려주세요. 볼리베어가 라인에서 보이지 않으면 강가 쪽 다이브를 준비하는 경우가 많으니 웨이브를 내 포탑 앞에 두고 기다리세요.', item: '요우무의 유령검의 이동 속도로 (E)\'천공 분열\' 둔화를 맞은 뒤에도 볼리베어에게 다시 붙으세요. 신발은 기절과 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'광란의 상처\' 회복을 줄이세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 피해를 주고 회복하며, (E)\'선혈의 파도\'는 자신의 체력을 희생해 써요. 블라디미르가 (Q)\'수혈\'로 막타를 치러 다가오면 그 거리에서 바로 평타를 묻혀 출혈 피해로 회복분을 상쇄하세요. 블라디미르는 초반이 약하니 이 구간에 체력 차이를 크게 벌려 두세요.', lv3: '(W)\'피의 웅덩이\' 동안 블라디미르는 대상으로 지정되지 않으니, 블라디미르가 W를 쓰면 (E)\'포획\'을 아껴 두고 웅덩이가 끝나는 자리에 맞춰 쓰세요. (E)\'선혈의 파도\'는 미니언이 막을 수 있으니 미니언 뒤에 서서 피하세요. W가 빠진 블라디미르는 도망칠 수단이 없어서 (W)\'마비의 일격\' 둔화로 계속 붙어 있을 수 있어요.', lv6: '(R)\'혈사병\'에 걸리면 받는 피해가 커지니 블라디미르가 궁극기를 쓰면 바로 빠지세요. 출혈 중첩을 가득 쌓은 블라디미르에게는 W가 빠졌을 때 (R)\'녹서스의 단두대\'를 써야 피해지지 않아요. 블라디미르는 성장할수록 강해지니 라인을 밀어 포탑 골드를 챙기세요.', item: '회복이 큰 블라디미르에게는 요우무의 유령검과 처형인의 대검을 맞춰 회복을 줄이세요. 신발은 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'수혈\' 회복량을 줄여야 블라디미르를 처치할 수 있어요.' },
    '뽀삐': { lv1: '뽀삐는 (P)\'강철의 외교관\'으로 보호막을 얻고 (Q)\'망치 강타\'로 견제하며 둔화 지대를 만들어요. 망치 지대가 폭발하기 전에 빠지고, 뽀삐가 막타를 치러 다가오면 평타로 (P)\'과다출혈\'을 묻히세요. 뽀삐가 방패를 주우러 움직이는 길목을 압박해 보호막을 얻기 전에 교환을 거세요.', lv3: '(E)\'용감한 돌진\'은 나를 밀어 지형에 부딪히면 기절시키니, 뽀삐가 나와 벽 사이를 노리고 돌아오면 먼저 라인 가운데로 빠지세요. (W)\'굳건한 태세\'는 돌진하는 적을 막고 이동 스킬을 못 쓰게 하니, 이 스킬이 켜진 동안에는 무리하게 거리를 좁히려 하지 말고 끝난 뒤에 (E)\'포획\'으로 끌어오세요. 돌진이 빠진 뽀삐는 붙어 있는 나를 밀어낼 수단이 없어서, (Q)\'학살\' 바깥 날을 연달아 맞힐 시간이 나와요.', lv6: '(R)\'수호자의 심판\'에 맞으면 멀리 날아가니, 출혈을 쌓던 중 궁극기를 맞으면 처형 각이 끊겨요. (R)\'수호자의 심판\'을 허공에 쓴 뽀삐는 큰 한 방이 빠진 상태라, 다시 걸어 들어가 (W)\'마비의 일격\'과 바깥 날 (Q)\'학살\'로 중첩을 채운 뒤 (R)\'녹서스의 단두대\'를 꽂으세요. 뽀삐는 단단해서 처치가 오래 걸리니 라인을 밀어 포탑을 압박하세요.', item: '단단한 뽀삐에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 뽀삐의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 초반 킬각을 만들어 뽀삐의 성장을 늦추세요.' },
    '사이온': { lv1: '사이온이 (Q)\'대량 학살 강타\'를 충전할 때는 옆으로 비켜서서 헛치게 만드세요. (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나며 뒤의 적까지 맞으니 미니언 뒤로 숨지 마세요. 사이온이 충전을 준비하는 동안 (W)\'마비의 일격\'으로 견제하며 거리를 조절하세요.', lv3: '사이온이 (W)\'영혼의 용광로\'로 보호막을 씌우면 보호막이 터지기 전에 거리를 두세요. (Q)\'대량 학살 강타\'의 충전 동작이 보이면 정면에서 비켜서고, 내리친 뒤 빈틈에 (E)\'포획\'으로 끌어당겨 딜교환을 시작하세요. 딜교환 때는 (Q)\'학살\'의 도끼날을 맞히는 데 집중해 체력을 회복하세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진하니 (E)\'포획\'으로 끊으려 하지 말고 돌진 경로에서 벗어나 피하세요. 사이온이 쓰러져도 (P)\'영광스러운 죽음\'으로 잠시 되살아나 다시 공격하니 체력이 낮아 보여도 방심하지 마세요. (P)\'과다출혈\' 중첩을 충분히 쌓은 뒤 (R)\'녹서스의 단두대\'로 마무리하세요.', item: '판금 장화는 사이온의 기본 공격으로 받는 피해를 줄여줘요. 첫 코어 아이템은 칠흑의 양날 도끼를 선택해 방어력을 낮추고 전투를 이어가세요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 올리고 유닛과의 충돌을 무시해 미니언 사이를 지나 사이온에게 바로 붙을 수 있어요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 견제하고 (P)\'페트리사이트 폭발\'로 평타 피해를 더해요. 1~2레벨에는 사일러스가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, 사슬이 교차하는 지점을 피하세요. 사일러스는 초반 체력이 낮으니 웨이브를 밀어 압박하세요.', lv3: '(W)\'국왕시해자\'로 돌진하며 회복하니, 사일러스가 W를 쓰면 짧게 맞받고 빠지세요. (E)\'도주\'와 (E)\'억압\'으로 거리를 좁히는 사일러스에게 들어오는 순간 (Q)\'학살\' 바깥 날을 맞히세요. (E)\'도주\'와 (E)\'억압\'이 모두 빠진 사일러스는 벽을 넘을 수단이 없으니, 그 순간 (E)\'포획\'으로 끌어와 출혈을 채우세요.', lv6: '사일러스는 (R)\'강탈\'로 내 (R)\'녹서스의 단두대\'를 빼앗아 쓸 수 있으니, 궁극기를 훔쳐 간 뒤에는 체력이 낮은 상태로 싸움을 길게 끌지 마세요. 사일러스가 훔친 궁극기를 쓰고 나면 (W)\'국왕시해자\' 회복만 남으니, 출혈을 가득 채운 뒤 W가 빠진 순간 (R)\'녹서스의 단두대\'로 끊으세요. 훔친 궁극기가 갱킹용이면 정글러와의 연계가 무서워지니, 사일러스가 무엇을 훔쳤는지 보고 강가 쪽 이동을 조절하세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'도주\'로 빠지는 사일러스를 따라가세요. 신발은 사일러스의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\' 회복을 줄이세요.' },
    '세주아니': { lv1: '1~2레벨에는 (W)\'혹한의 서릿발\'의 둔화와 서리 중첩을 조심하며 짧게 딜교환하세요. (Q)\'학살\'의 도끼날 부분을 맞혀 체력을 회복하며 유지력 싸움을 하는 것이 좋아요. 상대가 (Q)\'혹한의 맹습\'으로 진입하면 거리를 조절하며 피해를 최소화하세요.', lv3: '(Q)\'혹한의 맹습\' 돌진을 피한 뒤 (E)\'포획\'으로 끌어당겨 공격을 시작하세요. (P)\'혹한의 분노\'의 서리 갑옷이 있으면 둔화에 면역이니, 갑옷이 사라진 것을 보고 (W)\'마비의 일격\'과 (Q)\'학살\'로 출혈 중첩을 쌓아 (E)\'만년 서리\' 기절 전에 피해를 넣으세요. 상대의 (W)\'혹한의 서릿발\' 휘두르기 동작에 맞춰 거리 조절을 하세요.', lv6: '(R)\'빙하 감옥\'에 맞으면 기절하므로 거리 유지에 신경 쓰세요. (E)\'포획\'으로 끌어온 뒤 빠르게 중첩을 쌓아 (R)\'녹서스의 단두대\'로 마무리하는 킬각을 잡으세요. 라인을 밀 때 상대 정글러가 개입하면 기절 연계가 강력하니 주의하세요.', item: '헤르메스의 발걸음과 발걸음 분쇄기를 추천해요. 강인함으로 (E)\'만년 서리\' 같은 기절 지속 시간을 줄이고, 공격력과 체력을 얻어 지속 전투 능력을 높이기 위해서예요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 거리를 좁히고 출혈 중첩을 쌓기 위해서예요.' },
    '세트': { lv1: '세트는 (P)\'투기장의 투지\'로 양 주먹을 번갈아 쓰며 1~2레벨 평타 교환이 강해요. 세트와 오래 평타 싸움을 하지 말고, 평타 두세 번으로 (P)\'과다출혈\'을 묻힌 뒤 빠져서 출혈 피해가 들어가게 하세요. 세트가 (Q)\'주먹다짐\'을 켜고 다가오면 뒤로 물러나 (Q)\'학살\' 바깥 날 거리를 만들어 두세요.', lv3: '(E)\'안면 강타\'는 세트 양옆에 적이 있으면 기절시키니, 세트가 나와 내 미니언 사이에 있을 때는 붙지 마세요. (W)\'강펀치\'는 받은 피해를 투지로 저장했다가 고정 피해와 보호막으로 바꾸니, 투지가 가득 찬 세트에게는 (E)\'포획\'을 아껴 두세요. W가 빠진 세트를 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날까지 이으면 회복을 챙기며 길게 싸울 수 있어요.', lv6: '(R)\'대미 장식\'은 나를 붙잡아 내리꽂으니, 출혈을 쌓던 중 궁극기에 잡히면 처형 각이 끊겨요. (R)\'대미 장식\'을 쓴 세트는 다시 붙잡을 수단이 없으니, 착지 직후 반 걸음 물러나 바깥 날 (Q)\'학살\'로 체력을 되찾으며 중첩을 마저 채우세요. 세트는 E 기절로 정글러와 연계하니 라인을 너무 깊게 밀지 마세요.', item: '요우무의 유령검의 이동 속도로 세트와 거리를 조절하다가 (W)\'강펀치\'가 빠진 뒤 다시 붙으세요. 신발은 세트의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'투기장의 투지\' 회복을 줄이세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 기의 검을 불러 최대 체력 비례 피해를 넣고, 스킬을 쓸 때마다 (P)\'기 보호막\'을 얻어요. 1~2레벨에는 쉔이 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, 기의 검이 지나가는 직선을 피하세요. 쉔은 (P)\'기 보호막\'이 켜진 순간 피해가 덜 들어가니, 보호막이 꺼진 직후에 (W)\'마비의 일격\'으로 중첩을 몰아 쌓으세요.', lv3: '(W)\'의지의 결계\'가 켜지면 쉔에 대한 평타가 막히니, 결계가 켜진 동안은 평타와 (W)\'마비의 일격\'을 아끼고 (Q)\'학살\'로 피해를 넣으세요. (E)\'그림자 돌진\'에 도발되면 쉔 쪽으로 걸어가게 되니, 쉔이 E를 쓰기 전에 무리하게 들어가지 마세요. 도발이 빠진 쉔은 나를 억지로 끌어들일 수단이 없으니, 바깥 날 거리를 여유 있게 맞춰 (Q)\'학살\'을 쓰세요.', lv6: '(R)\'단결된 의지\'로 쉔이 다른 라인에 가면 그 사이 라인을 밀고 포탑을 압박하세요. 쉔은 (P)\'기 보호막\'으로 피해를 흡수하니, 보호막이 꺼진 걸 확인하고 출혈을 가득 채운 뒤 (R)\'녹서스의 단두대\'를 쓰세요. 쉔의 궁극기가 돌아왔을 때 웨이브를 크게 밀어 두면 쉔은 합류와 라인 중 하나를 포기해야 해요.', item: '단단한 쉔에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (E)\'그림자 돌진\' 도발 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 합류할 때 순간이동으로 같이 따라가세요.' },
    '쉬바나': { lv1: '(Q)\'학살\'의 도끼날을 맞히며 (P)\'과다출혈\' 중첩을 쌓고 체력을 회복하는 것이 중요해요. 쉬바나의 (Q)\'잉걸불 일격\'은 다음 기본 공격을 강화하는 스킬이니 강화된 기본 공격을 맞는 교환은 짧게 끊으세요. 초반에는 무리하게 진입하기보다 미니언과 함께하며 기회를 엿봐요.', lv3: '상대가 (E)\'용암 분출\'로 둔화를 걸려고 할 때 (E)\'포획\'을 사용하여 거리를 좁히며 진입하세요. (W)\'지옥불 방패\'의 보호막이 빠진 상태에서 (W)\'마비의 일격\'과 (Q)\'학살\'을 연계하면 효율적으로 딜교환을 할 수 있어요. (P)\'과다출혈\'을 빠르게 쌓는 것에 집중하세요.', lv6: '(R)\'용의 강림\'의 불길에 닿으면 달아나게 되어 스킬을 쓸 수 없으니 변신 방향과 거리를 미리 살피세요. 변신 직후에는 저지 불가 상태가 되니 (E)\'포획\'은 그 뒤에 쓰고, (P)\'과다출혈\' 중첩이 쌓이면 (R)\'녹서스의 단두대\'로 마무리하세요. 용 형상으로 추가 체력을 얻으니 무리하지 말고 정글러를 부르거나 라인을 관리해요.', item: '헤르메스의 발걸음과 삼위일체를 가세요. 마법 저항력을 확보해 (E)\'용암 분출\'의 마법 피해를 견디고 삼위일체의 공격력과 체력으로 전투력을 높여야 해요.', spell: '점멸과 점화를 선택해요. (R)\'용의 강림\' 이후 용 형상에서 (W)\'지옥불 방패\'로 체력을 회복하는 것을 억제하고 확실하게 킬을 내기 위해서예요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 근거리 견제를 넣고 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'죽음의 손길\'은 앞으로 뻗는 번개라, 스웨인이 Q를 쓰려고 앞으로 나올 때 오히려 걸어 들어가 평타로 (P)\'과다출혈\'을 묻히세요. (P)\'굶주린 새떼\' 영혼 조각으로 최대 체력이 늘기 전인 초반에 체력 차이를 벌려 두세요.', lv3: '(E)\'속박명령\'에 맞으면 속박되고 끌려가니, 스웨인이 E를 쓰기 전에는 무리하게 들어가지 마세요. E가 빠진 스웨인은 도망칠 수단이 없으니 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 걸고 출혈 중첩을 채우세요. (W)\'제국의 눈\'은 멀리서 둔화를 거니 거리를 좁힐 때 피하세요.', lv6: '(R)\'악의 승천\'을 쓴 스웨인은 주변에서 생명력을 흡수하니, 미니언이 많은 곳에서 오래 싸우지 마세요. 출혈 중첩을 가득 쌓고 궁극기가 끝나기 전에 (R)\'녹서스의 단두대\'로 끝내야 회복을 막을 수 있어요. 스웨인은 탈출기가 없으니 정글러와 함께 노리면 확실해요.', item: '회복이 큰 스웨인에게는 요우무의 유령검과 처형인의 대검을 맞춰 회복을 줄이세요. 신발은 스웨인의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'악의 승천\' 회복을 줄여야 스웨인을 처치할 수 있어요.' },
    '스카너': { lv1: '1~2레벨에는 (Q)\'부서진 대지/지반 돌출\'의 강화 평타로 인한 둔화를 조심하면서 거리를 조절하세요. (Q)\'학살\'의 도끼날을 맞혀 체력을 회복하며 상대의 체력을 깎아내고 (P)\'과다출혈\' 중첩을 쌓으세요. 상대가 무리하게 다가올 때만 짧게 딜교환을 하며 압박하는 것이 좋아요.', lv3: '(E)\'이쉬탈의 격돌\'에 끌려 벽에 부딪혀 기절하지 않도록 벽에서 떨어진 곳에 자리를 잡으세요. 스카너가 다가오면 (E)\'포획\'으로 끌어당긴 뒤 (W)\'마비의 일격\'으로 이동 속도를 늦춰 공격하세요. (Q)\'학살\'로 빠르게 중첩을 쌓아 분노 상태를 만드는 것이 핵심이에요.', lv6: '(R)\'꿰뚫기\'에 맞으면 제압되어 스킬을 쓸 수 없고 스카너를 따라 끌려다니며 정화로도 풀 수 없으니, 상대의 주요 스킬이 빠진 뒤에 진입하세요. (E)\'포획\'으로 상대를 끌어당긴 후 (R)\'녹서스의 단두대\'를 사용해 고정 피해로 마무리하세요. 정글러의 개입이 예상될 때는 무리하지 말고 라인을 관리하며 버티세요.', item: '발걸음 분쇄기와 판금 장화를 추천해요. 발걸음 분쇄기의 체력과 둔화 효과로 적을 추격하기 좋고, 판금 장화는 기본 공격으로 받는 피해를 줄여주기 때문이에요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가로 거리를 좁혀 출혈 중첩을 쌓기 위해서예요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 뒤에 남기며 라인을 밀고, 쫓아오는 적을 독구름으로 유인해요. 신지드를 쫓아가지 말고 막타를 챙기며, 신지드가 미니언을 밀러 다가올 때 평타로 (P)\'과다출혈\'을 묻히세요. 독구름 위에 서 있지 않도록 위치를 잡으세요.', lv3: '(W)\'초강력 접착제\'를 밟으면 둔화되고 이동 스킬을 쓸 수 없으니, 접착제 위에서는 싸우지 마세요. (E)\'던져넘기기\'에 맞으면 신지드 뒤로 던져지니, 던져진 뒤 바로 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히세요. 신지드는 도망치는 대신 계속 독을 남기니 무리하게 쫓지 말고 기다리세요.', lv6: '(R)\'광기의 물약\'을 쓴 신지드는 (Q)\'맹독의 자취\'로 회복을 줄이니, 독구름 위에서 싸우지 마세요. (R)\'광기의 물약\'이 끝난 신지드에게 (E)\'포획\'을 던져 끌어오고, 출혈을 채워 (R)\'녹서스의 단두대\'로 끊어 주세요. 신지드가 라인을 빠르게 밀면 포탑 아래에서 막타를 챙기고, 갱킹 동선에 맞춰 길목을 막아 주세요.', item: '체력이 높은 신지드에게는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (Q)\'맹독의 자취\' 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 (P)\'독성 급류\'로 빨라지는 신지드를 따라가세요.' },
    '아이번': { lv1: '1~2레벨에는 아이번이 (Q)\'덩굴뿌리\'를 사용해 속박을 거는 타이밍을 조심하며 거리 조절을 하세요. (Q)\'학살\'을 사용할 때 도끼날 부분에 적중시켜 체력을 회복하며 (P)\'과다출혈\' 중첩을 쌓는 데 집중해요. 아이번의 (W)\'수풀 가꾸기\'로 인해 시야가 가려질 수 있으니 주의하며 미니언과 함께 움직이세요.', lv3: '스킬이 모이면 아이번의 (E)\'보호의 씨앗\'은 아군에게 보호막을 씌우고 폭발해 둔화시키니, 폭발 범위 안에서 오래 싸우지 마세요. (Q)\'덩굴뿌리\'는 처음으로 맞은 적을 속박하는 스킬이라 미니언 뒤에서 받아내 맞지 않게 하세요. (W)\'마비의 일격\'과 (Q)\'학살\' 도끼날을 맞히며 딜교환을 이어가세요.', lv6: '아이번이 (R)\'데이지!\'를 소환하면 데이지가 같은 챔피언을 연속으로 세 번 공격할 때 공중으로 띄우는 충격파를 조심하며 데이지와 거리를 두세요. (P)\'과다출혈\' 중첩을 쌓은 상태에서 (R)\'녹서스의 단두대\'로 아이번을 마무리하세요. 라인을 밀어 넣은 뒤 정글러를 호출하여 아이번을 압박하세요.', item: '헤르메스의 발걸음과 굶주린 히드라를 추천해요. 아이번의 마법 피해를 견디기 위해 헤르메스의 발걸음을 선택하고, 생명력 흡수와 쪼개기 효과를 위해 굶주린 히드라를 가세요.', spell: '점멸과 점화. (R)\'녹서스의 단두대\'로 적을 마무리할 때 피해량을 높이기 위해 점화를 사용해요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'으로 견제할 때 무리하게 들어가지 마세요. (Q)\'학살\'의 도끼날은 챔피언에게 맞혀야 체력이 회복되니 미니언이 아닌 아지르를 범위에 넣을 때 쓰세요. 상대의 병사 공격 사거리 안으로 너무 자주 들어가지 않도록 주의하세요.', lv3: '아지르가 (E)\'신기루\'를 사용하여 위치를 옮길 때를 대비해 (E)\'포획\'을 신중하게 사용하세요. (E)\'포획\'으로 적을 끌어당긴 뒤 (W)\'마비의 일격\'을 맞혀 이동 속도를 늦추면 딜교환을 하기 편해요. (Q)\'사막의 맹습\'에 맞지 않도록 거리를 조절하며 접근하세요.', lv6: '아지르의 (R)\'황제의 진영\'은 적들을 밀어내고 병사들이 남아 길을 가로막으니, 쓰기 전에 (E)\'포획\'을 먼저 맞히는 각을 보세요. (P)\'과다출혈\' 중첩을 쌓은 상태에서 (R)\'녹서스의 단두대\'로 킬을 노려보세요. 라인을 당겨 관리하며 정글러의 도움을 받는 것도 좋아요.', item: '헤르메스의 발걸음과 삼위일체를 가세요. 아지르의 마법 피해를 견디고 전투를 지속하기 위해서예요.', spell: '점멸과 유체화를 선택해요. 유체화로 아지르와의 거리를 빠르게 좁혀 접근하기 위해서예요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 견제하고 (P)\'암살자의 표식\' 원을 넘으면 평타 사거리와 피해가 늘어나요. 아칼리가 (P)\'암살자의 표식\' 원 밖으로 나갔다 들어오며 강화 평타를 노리면, 원 경계 근처에서 같이 평타를 맞받아 (P)\'과다출혈\'을 두세 번 쌓아 두세요. 아칼리는 기력이 떨어지면 견제를 못 하니 기력이 빠진 뒤에 압박하세요.', lv3: '(W)\'황혼의 장막\' 안에서는 아칼리를 대상으로 지정할 수 없으니, 연막 안에서는 (Q)\'학살\'처럼 범위로 맞히는 스킬을 쓰세요. (E)\'표창곡예\' 표식이 남으면 아칼리가 다시 돌진하니, E가 빠진 뒤에 (E)\'포획\'으로 끌어와 출혈 중첩을 채우세요. 연막이 끝난 뒤에 (W)\'마비의 일격\' 둔화를 걸면 아칼리가 빠지기 어려워요.', lv6: '(R)\'무결처형\'으로 아칼리가 두 번 돌진하니, 체력이 낮을 때는 궁극기가 빠지기 전에 무리하게 싸우지 마세요. (R)\'녹서스의 단두대\'는 대상 지정이라 연막 안의 아칼리에게는 쓸 수 없으니 연막 밖으로 나온 순간 쓰세요. 아칼리는 체력이 낮아 출혈 중첩만 쌓이면 처형이 잘 들어가요.', item: '요우무의 유령검을 첫 코어로 가서 (R)\'무결처형\'으로 빠지는 아칼리를 따라가세요. 신발은 아칼리의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 연막 밖에서 마무리 피해를 더하세요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\' 견제는 적에게 맞을 때마다 사거리가 늘어나니 맞는 횟수를 줄이며 체력을 보존하세요. 첫 웨이브는 빠르게 정리하고 경험치를 챙기며 (Q)\'학살\'은 도끼날로 챔피언을 맞힐 때 쓰세요. 무리하게 딜교환을 시도하지 말고 거리 조절에 집중하세요.', lv3: '(E)\'포획\'을 정확히 맞히는 것이 딜교환의 핵심이에요. (E)\'포획\' 이후 즉시 (W)\'마비의 일격\'으로 둔화시키고 (Q)\'학살\'의 도끼날로 출혈 중첩을 빠르게 쌓으세요. 상대가 (E)\'영웅의 비상\'으로 도망치거나 거리를 벌리기 전에 빠르게 접근해 피해를 입히세요.', lv6: '출혈 중첩을 쌓은 뒤 (R)\'녹서스의 단두대\'로 마무리하는 킬각을 노리세요. 하지만 상대의 (R)\'인과응보\'는 잃은 체력에 비례해 큰 피해를 입히므로 체력 관리에 유의하세요. 라인을 당겨 (E)\'포획\' 각을 만들고 정글러와 협력해 아크샨을 강하게 압박하세요.', item: '판금 장화와 발걸음 분쇄기. 판금 장화는 기본 공격 피해를 줄여주고 발걸음 분쇄기는 체력과 공격력을 제공하며 둔화 효과로 아크샨을 추격하기 좋기 때문이에요.', spell: '점멸과 유체화. 원거리 챔피언인 아크샨을 끝까지 추격해 (R)\'녹서스의 단두대\'까지 연결하기 위해 이동 속도가 매우 중요해요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\'을 세 번 휘두르며 각 공격의 피해 범위가 달라, 끝자락에 맞으면 피해가 커요. 1~2레벨에는 Q 끝자락을 피하며 막타를 받고, 아트록스가 Q를 다 쓴 뒤에 평타로 (P)\'과다출혈\'을 묻히세요. (P)\'사신 태세\'가 켜진 평타는 회복까지 하니 오래 붙어 있지 마세요.', lv3: '(W)\'지옥사슬\'에 맞으면 일정 시간 안에 범위를 벗어나지 않으면 끌려가니, W를 맞은 뒤 바로 빠지세요. (E)\'파멸의 돌진\'으로 Q 범위를 조절하는 아트록스에게는 Q 사이사이 빈틈에 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히세요. 아트록스의 Q가 다 빠진 뒤에 몰아치면 회복을 막을 수 있어요.', lv6: '(R)\'세계의 종결자\'를 쓴 아트록스는 공격력과 회복량이 늘어나니, 궁극기 지속시간 동안은 거리를 벌리세요. (R)\'세계의 종결자\'가 끝나면 (E)\'포획\'으로 다시 끌어와 출혈을 채우고 (R)\'녹서스의 단두대\' 고정 피해로 마무리하세요. 아트록스는 처치에 관여하면 궁극기가 연장되니 정글러와 함께 싸울 때 조심하세요.', item: '회복이 큰 아트록스에게는 요우무의 유령검과 처형인의 대검을 맞춰 회복을 줄이세요. 신발은 아트록스의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'세계의 종결자\' 회복을 줄이세요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬을 쓴 뒤 짧게 돌진하며 다음 평타를 강화해요. 1~2레벨에는 암베사가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, (Q)\'교활한 휩쓸기\' 날 끝에 맞지 않도록 거리를 조절하세요. 암베사가 스킬을 다 쓴 뒤에 압박하는 게 좋아요.', lv3: '(W)\'배척\'은 준비하는 동안 피해를 막으면 강해지니, 암베사가 W를 준비하면 평타를 멈추고 기다리세요. (E)\'찢어 가르기\' 둔화에 걸리면 (Q)\'학살\' 바깥 날 거리를 잡기 어려우니 E를 피한 뒤에 (E)\'포획\'으로 끌어오세요. 스킬이 빠진 암베사를 (W)\'마비의 일격\'으로 둔화시키면 돌진으로 빠지기 어려워요.', lv6: '(R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적 챔피언에게 순간 이동해 제압하니, 미니언 뒤에 있어도 안전하지 않다는 걸 기억하고 체력이 낮을 때는 사거리 밖으로 빠지세요. (R)\'공개 처형\'을 쓴 암베사가 (P)\'용사냥개의 발걸음\' 돌진으로 빠지려 할 때 (W)\'마비의 일격\' 둔화로 붙잡고, 중첩이 차면 (R)\'녹서스의 단두대\'로 끝내세요. (R)\'공개 처형\'에 정글러의 이동 불가 효과가 겹치면 빠져나올 시간이 없으니, 강가 시야가 없을 때는 웨이브를 내 포탑 앞에서 받으세요.', item: '요우무의 유령검을 첫 코어로 가서 (P)\'용사냥개의 발걸음\' 돌진으로 빠지는 암베사를 따라가세요. 신발은 암베사의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리를 더해야 암베사가 빠지기 전에 처치할 수 있어요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 기절을 걸고 냉기에 맞은 대상에게 (E)\'동상\' 피해를 두 배로 넣어요. (Q)\'냉기 폭발\'은 느리게 날아가니 옆으로 비켜 걸으며 다가가, 애니비아가 Q를 쓴 직후 평타로 (P)\'과다출혈\'을 묻히세요. 애니비아는 (W)\'결정화\'를 쓰기 전까지 접근을 막을 수단이 (Q)\'냉기 폭발\'뿐이라, Q를 피했다면 끝까지 붙어서 웨이브를 밀어 주세요.', lv3: '(W)\'결정화\' 얼음 벽에 막히면 거리를 좁히기 어려우니, 애니비아가 W를 쓴 뒤에 들어가세요. Q가 빠진 애니비아는 기절을 걸 수 없으니 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요. 애니비아는 탈출기가 없어서 끌려오면 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'얼음 폭풍\' 장판 안에서는 둔화 때문에 바깥 날 거리를 맞추기 어려우니, 장판 밖에서 (E)\'포획\'으로 애니비아를 끌어와 싸우세요. 애니비아는 치명적인 피해를 입으면 (P)\'환생\'으로 알이 되어 체력을 되찾으니, (R)\'녹서스의 단두대\'로 쓰러뜨린 뒤에도 자리를 뜨지 말고 알을 공격하세요. 애니비아는 탈출기가 없으니 (W)\'결정화\'만 빠지면 정글러와 함께 노리기 쉬워요.', item: '요우무의 유령검을 첫 코어로 가서 (R)\'얼음 폭풍\' 둔화를 이동 속도로 이겨내세요. 신발은 애니비아의 마법 피해와 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'냉기 폭발\'과 (R)\'얼음 폭풍\' 둔화 속에서도 거리를 좁힐 수 있어요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 견제하며 이번 패치에 피해가 소폭 내려갔지만, (P)\'낭인의 길\' 보호막 때문에 첫 교환 피해가 덜 들어가요. 평타 한 번으로 보호막을 먼저 터뜨린 뒤 (W)\'마비의 일격\'으로 (P)\'과다출혈\'을 묻히세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 들어오면 착지 지점에 맞춰 평타를 맞받으세요.', lv3: '(Q)\'강철 폭풍\'이 두 번 쌓이면 회오리로 띄우니, 야스오의 Q 중첩이 찼을 때는 회오리 직선을 피한 뒤에 (E)\'포획\'으로 끌어오세요. (E)\'질풍검\'은 같은 대상에게 바로 다시 쓸 수 없으니, 미니언이 적은 쪽으로 끌어오면 야스오가 빠질 길이 줄어요. 끌어온 직후 (Q)\'학살\' 바깥 날을 맞히면 보호막이 다시 차기 전에 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'최후의 숨결\'은 공중에 뜬 적에게 쓰니, 회오리에 맞지 않는 게 궁극기를 피하는 가장 확실한 방법이에요. (E)\'질풍검\'으로 미니언을 타고 빠지기 전에 출혈이 가득 찬 야스오에게 (R)\'녹서스의 단두대\'를 꽂아야 하니, 미니언 쪽으로 몸을 돌리는 순간을 보세요. 상대 정글러가 띄우는 스킬을 가지고 있다면 야스오 궁극기 연계를 조심하세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'질풍검\'으로 미니언을 타고 빠지는 야스오를 따라가세요. 신발은 야스오의 치명타 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'낭인의 길\' 보호막 이후 마무리 피해를 더하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 견제하며 방어력을 낮추고, (P)\'바위 피부\'로 싸울수록 단단해져요. 1~2레벨에는 오공이 Q를 쓴 뒤에 평타로 (P)\'과다출혈\'을 묻히고 오래 붙어 있지 마세요. 오공이 (E)\'근두운 급습\'으로 들어오면 착지 지점 주변으로 (Q)\'학살\' 바깥 날을 맞힐 준비를 하세요.', lv3: '(W)\'분신 전사\'로 투명해지며 분신을 남기니, 분신에 (E)\'포획\'을 낭비하지 말고 실제 오공이 보일 때 끌어오세요. (E)\'근두운 급습\'으로 들어온 오공에게 바로 (Q)\'학살\' 바깥 날을 맞히면 회복을 챙기며 맞받을 수 있어요. W가 빠진 오공은 도망칠 수단이 줄어드니 (W)\'마비의 일격\' 둔화로 계속 붙으세요.', lv6: '(R)\'회전격\'에 맞으면 공중에 뜨니, 출혈을 쌓던 중 궁극기에 맞으면 처형 각이 끊겨요. (R)\'회전격\'을 써 버린 오공은 (W)\'분신 전사\'와 (E)\'근두운 급습\' 말고는 빠질 길이 없으니, 투명이 풀리는 자리를 예상해 (E)\'포획\'을 던지고 (R)\'녹서스의 단두대\'까지 이으세요. 상대 정글러가 (R)\'회전격\' 띄우기에 맞춰 들어오는 갱킹이 위험하니 강가 쪽 수풀에 와드를 먼저 두세요.', item: '요우무의 유령검을 첫 코어로 가서 (W)\'분신 전사\'로 빠지는 오공을 따라가세요. 신발은 오공의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'바위 피부\' 체력 재생을 줄이세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'로 멀리서 견제하고 (P)\'영혼 방호술\'로 체력을 회복해요. (Q)\'이중 저주\'가 되돌아오는 경로를 피해 서고, 오로라가 Q를 쓴 직후 다가가 평타로 (P)\'과다출혈\'을 묻히세요. 오로라는 근접 압박에 약하니 웨이브를 밀어 압박하세요.', lv3: '(E)\'마법의 문\'은 둔화를 건 뒤 뒤로 뛰니, 오로라가 E를 쓴 뒤에 거리를 좁히세요. (W)\'장막 너머로\'로 투명해지는 오로라를 무리하게 쫓지 말고, W가 빠진 뒤에 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요. 끌려온 오로라에게 (Q)\'학살\' 바깥 날을 맞히면 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'세계의 경계\'는 오로라가 영역 안에서 이동할 수 있게 해 주니, 궁극기 영역 안에서 오래 싸우지 마세요. 출혈 중첩을 가득 쌓은 오로라가 영역 밖으로 나온 순간 (R)\'녹서스의 단두대\'로 끝내세요. 오로라는 갱킹이 오면 (W)\'장막 너머로\'로 빠지니, 정글러가 오기 전에 W를 먼저 쓰게 만드는 견제를 해 두세요.', item: '요우무의 유령검을 첫 코어로 가서 (W)\'장막 너머로\' 이후 거리를 벌리는 오로라를 따라가세요. 신발은 오로라의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 (E)\'마법의 문\'으로 뒤로 뛴 오로라와의 거리를 다시 좁히세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\'으로 방어력과 마법 저항력이 높고, (Q)\'용암 균열\'로 둔화를 걸며 견제해요. 1~2레벨에는 (Q)\'용암 균열\' 기둥이 솟는 자리를 옆으로 비켜서고, 오른이 균열을 쓴 직후 걸어가 평타로 (P)\'과다출혈\'을 계속 남기세요. 오른이 (E)\'화염 돌진\'을 미니언 정리에 쓰면 들어올 수단이 없어지니, E가 빠진 시간에 웨이브를 밀어 포탑 쪽으로 몰아넣으세요.', lv3: '(E)\'화염 돌진\'으로 벽에 부딪히면 띄우니, 벽 근처에서는 (E)\'포획\'을 쓰기 전에 오른 위치를 확인하세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되니 W 끝자락을 피하세요. E가 빠진 오른을 (E)\'포획\'으로 끌어오면 (E)\'포획\'의 방어력 무시 효과로 출혈 피해가 잘 들어가요.', lv6: '(R)\'대장장이 신의 부름\'에 맞으면 둔화되고 불안정 상태가 되며, 방향이 바뀐 정령에 맞으면 띄워지니 궁극기 방향을 확인하세요. 오른은 (P)\'간이 대장간\'으로 방어력이 높지만 (R)\'녹서스의 단두대\'는 고정 피해라 방어력과 상관없으니, 출혈을 가득 채우는 데만 집중하세요. 오른은 라인에서 바로 아이템을 만들며 버티니 귀환 압박이 잘 안 통해서, 대신 웨이브를 밀어 포탑 골드를 노리세요.', item: '단단한 오른에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 오른의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 처치가 어려우니 순간이동으로 라인 손해를 줄이세요.' },
    '올라프': { lv1: '올라프는 (Q)\'역류\'로 도끼를 던져 방어력과 이동 속도를 깎고, 도끼를 다시 주우면 바로 또 던져요. 올라프가 도끼를 주우러 움직이는 길은 미리 알 수 있으니, 그 길목에서 기다렸다가 평타로 (P)\'과다출혈\'을 묻히세요. 1~2레벨부터 올라프는 평타 교환이 강하니 오래 붙어 있지 마세요.', lv3: '(W)\'버티기\'를 켠 올라프는 공격 속도와 보호막을 얻으니, W가 켜진 동안은 (Q)\'학살\' 바깥 날로 회복만 챙기고 빠지세요. (E)\'무모한 강타\'는 올라프 자신도 체력을 잃으니, 올라프가 E를 자주 쓰면 체력이 낮아진 틈을 노리세요. 체력이 낮은 올라프는 (P)\'광전사의 분노\'로 흡혈이 늘어나니 출혈을 쌓은 뒤 길게 붙지 말고 끝내세요.', lv6: '(R)\'라그나로크\'를 쓴 올라프는 이동 방해 효과에 면역이라 (E)\'포획\'으로 끌어올 수 없으니, 궁극기가 켜진 동안은 거리를 벌리세요. (R)\'라그나로크\'가 끝나면 (Q)\'역류\' 도끼를 주우러 움직이는 동선에 (E)\'포획\'을 던져 끌어오고, 흡혈로 버티기 전에 (R)\'녹서스의 단두대\'로 끊으세요. (R)\'라그나로크\'를 켠 올라프와 정글러가 함께 오면 묶을 수단이 없으니, 강가 시야가 없을 때는 라인을 깊게 밀지 마세요.', item: '요우무의 유령검과 처형인의 대검을 맞춰 (P)\'광전사의 분노\' 흡혈을 줄이세요. 신발은 올라프의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'광전사의 분노\' 회복을 줄이세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'으로 견제하고 (P)\'사냥꾼의 길\'로 두 번째 공격마다 마법 피해를 섞어요. 요네가 (Q)\'필멸의 검\'으로 막타를 칠 때 직선 옆으로 비켜서 다가가고, 두 번째 평타마다 마법 피해가 섞이니 맞교환은 출혈 두세 번까지만 하세요. 요네가 (E)\'영혼해방\'을 써 버린 동안에는 빠질 길이 마땅치 않으니, 그때 웨이브를 밀며 체력 차이를 벌리세요.', lv3: '(E)\'영혼해방\'으로 영혼이 나간 요네는 지속시간이 끝나면 원래 자리로 돌아가니, E를 쓴 요네를 쫓지 말고 육신이 있는 자리 근처에서 기다리세요. (Q)\'필멸의 검\'이 두 번 쌓이면 돌진하며 띄우니, Q 중첩이 찼을 때는 (E)\'포획\'을 아껴 두세요. (W)\'영혼 가르기\' 보호막이 끝난 뒤에 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히세요.', lv6: '(R)\'운명봉인\'은 경로의 적을 끌어당기니, 상대 정글러가 근처에 있을 때 맞으면 그대로 잡혀요. 출혈 중첩을 가득 쌓은 요네가 (E)\'영혼해방\'으로 돌아오는 자리에서 (R)\'녹서스의 단두대\'로 끝내세요. 요네는 정글러와 (R)\'운명봉인\'을 겹치는 갱킹이 강하니 강가 쪽 시야가 없을 때는 라인을 당겨 두세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'영혼해방\'이 끝나 육신으로 돌아간 요네에게 빠르게 다시 붙으세요. 신발은 요네의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'영혼 가르기\' 보호막 이후 마무리 피해를 더하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 잡으며 무덤을 만들고, (P)\'영혼의 길잡이\'로 안개 망령을 소환해요. 요릭이 (Q)\'최후의 의식\'으로 미니언 막타를 칠 때마다 무덤이 생기니, 그 타이밍에 다가가 평타를 묻혀 막타와 체력 중 하나를 포기하게 만드세요. 무덤이 많이 쌓인 요릭은 망령으로 맞교환을 이기려 하니, 망령이 나오기 전에 짧게 끊는 교환을 하세요.', lv3: '(W)\'망자의 진\' 벽에 갇히면 도망치기 어려우니, 요릭이 W를 쓰면 벽을 평타로 부수거나 (E)\'포획\'으로 요릭을 끌어오세요. (E)\'애도의 안개\'는 방어력을 낮추고 표식을 남기니, E를 맞은 뒤에는 망령이 몰려오기 전에 (Q)\'학살\' 바깥 날로 망령과 요릭을 같이 맞히세요. 망령이 사라진 요릭은 혼자서 버티기 어려워요.', lv6: '(R)\'군도의 장송곡\'으로 안개 마녀가 소환되면 요릭과 함께 싸우기 어려우니, (Q)\'학살\'로 안개 마녀와 망령을 먼저 정리하세요. 출혈 중첩을 가득 쌓은 요릭에게 (R)\'녹서스의 단두대\'를 써서 마무리하세요. 안개 마녀와 망령은 포탑을 빠르게 깎으니, 웨이브를 내 포탑 앞에서 받아 망령을 (Q)\'학살\'로 정리하세요.', item: '요우무의 유령검의 이동 속도로 (E)\'애도의 안개\' 둔화를 맞은 뒤에도 요릭에게 다시 붙으세요. 신발은 요릭의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 요릭이 라인을 밀면 순간이동으로 빠르게 돌아오세요.' },
    '우디르': { lv1: '우디르는 태세를 바꾸며 (Q)\'야생 발톱\'으로 평타 피해를 늘리고 (W)\'강철 갑옷\'으로 보호막을 얻어요. 1~2레벨에는 우디르가 (E)\'불길 쇄도\'로 다가오면 기절을 맞으니, 뒤로 물러나 (Q)\'학살\' 바깥 날 거리를 만들어 두세요. 기절을 맞았다면 평타로 (P)\'과다출혈\'을 맞받으세요.', lv3: '(E)\'불길 쇄도\' 태세의 첫 평타는 기절을 거니, 우디르가 E를 쓴 뒤 첫 평타를 맞은 다음에 (E)\'포획\'으로 끌어오세요. (W)\'강철 갑옷\'을 켠 우디르는 다음 평타 두 번으로 체력도 회복하니, 그 두 번을 (E)\'포획\' 거리 밖에서 흘려보낸 뒤 들어가세요. 끌려온 우디르에게 바깥 날 (Q)\'학살\'을 맞히고 (W)\'마비의 일격\'으로 이어 붙이면 태세를 바꿔 빠지기 전에 출혈이 가득 차요.', lv6: '(R)\'날개 돋친 폭풍\'을 두른 우디르 곁에서는 둔화가 계속되니, 폭풍이 꺼진 뒤 (E)\'포획\'으로 끌어오세요. 우디르가 (E)\'불길 쇄도\'를 재사용하면 이동 불가 효과에 면역이 되니 (E)\'포획\'을 그 시간에 쓰지 마세요. 우디르는 태세를 바꿀 때마다 다음 평타 두 번이 빨라지니, 그 두 번이 끝난 틈에 출혈을 채워 (R)\'녹서스의 단두대\'를 꽂으세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'불길 쇄도\'로 빠지는 우디르를 따라가세요. 신발은 우디르의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'강철 갑옷\' 회복을 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (P)\'화염의 메아리\'로 평타마다 다리에서 불꽃을 쏘며 견제하고, (Q)\'부식성 폭약\'으로 둔화를 걸어요. (Q)\'부식성 폭약\'이 떨어지는 원을 옆으로 비켜 피한 뒤 우르곳에게 걸어가 평타를 묻히면 둔화 없이 (P)\'과다출혈\'을 쌓을 수 있어요. 우르곳은 사거리가 길어 견제가 강하니 오래 교환하지 마세요.', lv3: '(W)\'심판의 원\'을 켠 우르곳은 둔화된 채로 주변을 계속 사격하니, W가 켜진 동안은 (Q)\'학살\' 바깥 날만 맞히고 빠졌다가 W가 끝난 뒤 (E)\'포획\'으로 끌어오세요. (E)\'경멸\'에 맞으면 우르곳 뒤로 던져지니, E가 빠진 뒤에 들어가세요. 우르곳은 탈출기가 적어 끌려오면 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'불사의 공포\'가 꽂힌 상태에서 체력이 낮아지면 우르곳에게 처형될 수 있으니, 궁극기가 꽂혔을 때는 우르곳과 거리를 벌리세요. 출혈 중첩을 가득 쌓은 우르곳에게 (R)\'녹서스의 단두대\'를 먼저 써서 끝내는 게 안전해요. (E)\'경멸\'로 나를 정글러 쪽으로 던지는 연계가 위험하니, 우르곳과 강가 사이에 서지 않도록 위치를 잡으세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'경멸\'로 빠지는 우르곳을 따라가세요. 신발은 우르곳의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 내가 (R)\'불사의 공포\' 처형선에 들어가기 전에 싸움을 끝내세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 최대 체력 비례 피해를 넣고 같은 만큼 회복하며, 체력이 낮아지면 (P)\'끝없는 허기\'로 회복이 늘어나요. 1~2레벨에는 워윅이 Q로 들어오면 평타로 (P)\'과다출혈\'을 맞받고 오래 붙어 있지 마세요. 워윅은 회복이 강하니 출혈을 쉬지 않고 이어 붙이세요.', lv3: '(E)\'원시의 포효\'를 켠 워윅은 받는 피해가 줄고 끝나면 나를 도망치게 하니, E가 켜진 동안은 (E)\'포획\'을 아껴 두세요. (W)\'피의 사냥\'은 체력이 낮은 적을 감지해 공격 속도를 올리니, 내 체력이 낮을 때는 무리하게 싸우지 마세요. E가 빠진 워윅을 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히면 회복 싸움에서 이길 수 있어요.', lv6: '(R)\'무한의 구속\'은 도약해 제압하니, 상대 정글러가 근처에 있을 때 맞으면 그대로 잡혀요. 출혈 중첩을 가득 쌓은 워윅에게 (R)\'녹서스의 단두대\'를 써서 회복이 들어가기 전에 끝내세요. 제압은 정화로 풀 수 없으니, 워윅의 궁극기가 남아 있을 때 체력이 낮다면 (W)\'피의 사냥\'에 감지되지 않게 라인을 당겨 두세요.', item: '회복이 큰 워윅에게는 요우무의 유령검과 처형인의 대검을 맞춰 회복을 줄이세요. 신발은 워윅의 마법 피해와 공포 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'야수의 송곳니\' 회복을 줄이세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 들어와 체력을 회복하며, 처치하면 재사용 대기시간이 초기화돼요. 1~2레벨에는 이렐리아가 Q로 들어오면 평타로 (P)\'과다출혈\'을 맞받고 (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 빠지세요. 미니언 체력이 낮은 쪽에 서 있으면 이렐리아가 그 미니언을 타고 들어오니 위치를 조심하세요.', lv3: '(E)\'쌍검협무\'에 맞으면 기절하고 표식이 생겨 Q가 초기화되니, 두 칼날이 만나는 직선을 피하세요. (W)\'저항의 춤\'을 충전하는 동안 이렐리아가 받는 물리 피해가 줄어드니 그때 (Q)\'학살\'을 쓰지 말고 끝난 뒤에 쓰세요. E가 빠진 이렐리아를 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 걸면 Q로 빠지기 어려워요.', lv6: '(R)\'선봉진격검\'은 표식을 남기고 결계를 만드니, 결계를 통과하지 않도록 위치를 잡으세요. 출혈 중첩을 가득 쌓은 이렐리아가 Q로 빠지기 전에 (R)\'녹서스의 단두대\'로 끝내세요. 이렐리아는 처치하면 Q가 초기화되니 미니언이 많은 곳에서 싸우지 마세요.', item: '요우무의 유령검을 첫 코어로 가서 (Q)\'칼날 쇄도\'로 빠지는 이렐리아를 따라가세요. 신발은 이렐리아의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\' 회복을 줄이세요.' },
    '일라오이': { lv1: '일라오이는 (Q)\'촉수 강타\'로 견제하고 (P)\'고대신의 예언자\' 촉수로 주변 지형에서 공격해요. 1~2레벨에는 벽 근처를 피해 라인 한가운데에 서서, 일라오이가 (Q)\'촉수 강타\'를 미니언에 쓴 직후 걸어가 (P)\'과다출혈\'을 남기세요. 촉수가 적은 곳에서 싸우면 일라오이의 피해가 크게 줄어요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼이 받은 피해 일부가 나에게 돌아오고 영혼에서 멀어지면 숙주가 되어 촉수가 나를 노리니, E에 맞은 상태로 벽 근처에서 오래 싸우지 마세요. E가 빠진 일라오이를 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히면 촉수가 없는 곳에서 싸울 수 있어요. (W)\'혹독한 가르침\'으로 도약하는 일라오이에게는 착지 지점에서 맞받으세요.', lv6: '(R)\'믿음의 도약\'은 주변 챔피언 수만큼 촉수를 소환하니, 궁극기 범위 안에서 오래 싸우지 마세요. 일라오이가 궁극기를 쓴 뒤 촉수가 사라질 때까지 거리를 벌렸다가 출혈 중첩을 가득 쌓고 (R)\'녹서스의 단두대\'로 마무리하세요. 일라오이는 정글러와 함께 싸우기 좋으니 라인을 당겨 받으세요.', item: '요우무의 유령검과 처형인의 대검을 맞춰 촉수 공격으로 체력을 채우는 일라오이의 회복을 줄이세요. 신발은 일라오이의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'영혼의 시험\' 사거리 밖으로 빠르게 빠지세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 붙잡아 견제하고 (P)\'세포 분열\'로 떨어진 조각을 흡수해 회복해요. 1~2레벨에는 자크가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, 자크가 떨어진 조각을 주우러 움직이는 동선에 맞춰 압박하세요. 1~2레벨 자크는 스킬이 적어 버티는 힘이 약하니, 웨이브를 상대 포탑 쪽으로 밀어 두고 (W)\'마비의 일격\'까지 섞어 체력 차이를 벌리세요.', lv3: '(W)\'불안정 물질\'은 최대 체력 비례 피해를 주니, 자크가 W를 쓰면 짧게 맞받고 빠지세요. (E)\'새총 발사\'로 날아든 자크가 착지하자마자 반 걸음 물러나 (Q)\'학살\' 바깥 날 거리를 만드세요. E가 빠진 자크를 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 걸면 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'바운스!\'는 적중당한 적을 띄우니, 출혈을 쌓던 중 궁극기에 맞으면 처형 각이 끊겨요. 자크는 쓰러지면 조각으로 갈라졌다가 부활하니, (R)\'녹서스의 단두대\'로 처치한 뒤 조각을 (Q)\'학살\'로 정리하세요. (P)\'세포 분열\' 부활은 한참 뒤에야 다시 돌아오니, 한 번 부활을 빼냈다면 다음 싸움은 훨씬 짧게 끝낼 수 있어요.', item: '단단한 자크에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 자크의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'세포 분열\' 회복을 줄이세요.' },
    '자헨': { lv1: '자헨은 (P)\'전쟁 단련\'으로 평타와 스킬을 맞힐 때마다 결심 중첩을 쌓아 공격력을 올려요. 1~2레벨에는 자헨이 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 회복하니, Q가 빠진 뒤에 평타로 (P)\'과다출혈\'을 묻히세요. 자헨과 오래 평타 싸움을 하면 결심 중첩이 쌓이니 짧게 교환하세요.', lv3: '(W)\'공포의 귀환\'에 맞으면 끌려가니, W 직선을 피한 뒤에 (E)\'포획\'으로 끌어오세요. (E)\'찬란한 쇄도\'로 들어오는 자헨에게 착지 지점에서 (Q)\'학살\' 바깥 날을 맞히세요. Q 재사용으로 띄우는 공격이 있으니 자헨의 Q가 빠졌는지 확인하고 들어가세요.', lv6: '(R)\'단호한 판결\'은 날아올라 내려찍으며 회복하니, 궁극기 착지 지점을 피하세요. 결심이 가득 찬 자헨은 부활할 수 있으니, (R)\'녹서스의 단두대\'로 처치한 뒤에도 바로 빠지세요. 출혈 중첩을 가득 쌓고 결심이 차기 전에 처치하는 게 안전해요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'찬란한 쇄도\'로 빠지는 자헨을 따라가세요. 신발은 자헨의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'다르킨의 글레이브\' 회복을 줄이세요.' },
    '잭스': { lv1: '잭스는 (Q)\'도약 공격\'으로 들어오고 (W)\'무기 강화\'로 평타를 강화해요. 1~2레벨에는 잭스가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, (P)\'가차없는 맹공\'으로 공격 속도가 오르기 전에 빠지세요. 잭스가 (W)\'무기 강화\'를 막타에 쓰면 평타 교환 화력이 크게 줄어드니, W를 미니언에 쓴 직후에 걸어 들어가세요.', lv3: '(E)\'반격\'을 켠 잭스는 공격을 모두 피하고 기절을 거니, E가 켜진 동안은 평타를 치지 말고 (Q)\'학살\' 바깥 날 거리로 물러나세요. (E)\'반격\'이 끝난 뒤에 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\'까지 넣으면 출혈 중첩을 빠르게 채울 수 있어요. (Q)\'도약 공격\'은 대상을 지정해 뛰는 스킬이라 둔화로는 막을 수 없으니, 잭스가 근처 미니언으로 빠지기 전에 몰아치세요.', lv6: '(R)\'무기의 달인\'을 쓴 잭스는 방어력과 마법 저항력이 오르니, 궁극기 지속시간 동안은 거리를 벌리세요. (E)\'반격\' 기절이 끝나고 잭스가 (Q)\'도약 공격\'으로 미니언을 타고 빠지려 할 때, 묻혀 둔 출혈만으로 (R)\'녹서스의 단두대\' 처형선이 되는지 체력바를 보고 판단하세요. 잭스는 아이템이 쌓일수록 (P)\'가차없는 맹공\'과 (R)\'무기의 달인\'이 무서워지니, 라인전 동안 포탑 골드와 킬로 성장 차이를 벌려 두세요.', item: '요우무의 유령검을 첫 코어로 가서 (Q)\'도약 공격\'으로 빠지는 잭스를 따라가세요. 신발은 잭스의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 잭스가 (Q)\'도약 공격\'으로 빠져도 처치를 마무리하세요.' },
    '제이스': { lv1: '제이스는 캐논 형태에서 (Q)\'전격 폭발\'로 멀리서 견제하고, 해머 형태로 바꿔 (E)\'천둥 강타\'로 밀쳐내요. 캐논 상태의 제이스가 막타를 치러 앞으로 나오면 (Q)\'전격 폭발\' 직선 밖에서 비스듬히 다가가 평타로 (P)\'과다출혈\'을 묻히세요. 제이스가 해머로 들어오면 (Q)\'학살\' 바깥 날로 맞받을 준비를 하세요.', lv3: '(E)\'천둥 강타\'에 밀려나면 출혈을 이어 쌓기 어려우니, 제이스가 해머 E를 쓴 뒤에 (E)\'포획\'으로 다시 끌어오세요. (E)\'가속 관문\'을 통과한 (Q)\'전격 폭발\'은 피해가 커지니 관문이 열리면 직선에서 벗어나세요. 끌어온 제이스에게 (W)\'마비의 일격\' 둔화를 걸면 형태를 바꿔 도망치기 어려워요.', lv6: '6레벨 이후 제이스는 (R)\'머큐리 캐논\'과 (R)\'머큐리 해머\'를 오가며 형태를 바꾸니, 캐논 형태로 견제할 때는 (Q)\'전격 폭발\' 직선을 피해 체력을 지키세요. 해머 (E)\'천둥 강타\'를 쓴 직후에는 나를 다시 밀어낼 수단이 없으니, 그때 (E)\'포획\'으로 끌어와 출혈을 가득 채우고 (R)\'녹서스의 단두대\'로 끝내세요. 캐논 형태 제이스는 (E)\'가속 관문\'을 지나 빠르게 빠질 수 있으니 관문을 연 직후에는 무리하게 쫓지 마세요.', item: '요우무의 유령검을 첫 코어로 가서 캐논 사거리 밖에서 빠르게 거리를 좁히세요. 신발은 제이스의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'천둥 강타\'에 밀린 뒤 거리를 다시 좁히세요.' },
    '초가스': { lv1: '초가스는 (E)\'날카로운 가시\'로 평타마다 전방에 피해와 둔화를 주고, (P)\'육식\'으로 미니언을 잡으며 회복해요. 1~2레벨에는 초가스가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히고, (Q)\'파열\'이 떨어지는 원을 피하세요. 초가스는 (P)\'육식\'으로 미니언을 잡을 때마다 회복하니, 막타 직후마다 평타로 출혈을 다시 묻혀 회복분을 지워 주세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 (E)\'포획\'과 (Q)\'학살\'을 쓸 수 없으니, 초가스가 W를 쓴 뒤에 들어가세요. (Q)\'파열\' 원을 피한 뒤, 초가스가 다시 Q를 쓰기 전에 (E)\'포획\'으로 끌어오세요. 스킬이 빠진 초가스는 거리를 벌리기 어려우니 (W)\'마비의 일격\' 둔화로 계속 붙으세요.', lv6: '(R)\'포식\'은 큰 고정 피해를 주니, 체력이 낮을 때는 초가스와 가까이 있지 마세요. 초가스는 (R)\'포식\'으로 처치할 때마다 성장하니, 출혈 중첩을 가득 쌓고 (R)\'녹서스의 단두대\'로 먼저 끝내세요. 초가스가 (R)\'포식\'을 미니언에 쓰면 처형 걱정이 사라지니, 그 틈이 (E)\'포획\'으로 끌어와 길게 싸울 시간이에요.', item: '체력이 높은 초가스에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 초가스의 마법 피해와 침묵 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\' 회복을 줄이세요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 평타를 칠 때마다 보호막을 얻고, (Q)\'정확성 프로토콜\'로 강화 평타를 넣어요. 1~2레벨에는 카밀이 Q로 들어오면 평타로 (P)\'과다출혈\'을 맞받고, 보호막이 끝난 뒤에 몰아치세요. (Q)\'정확성 프로토콜\'은 기다렸다 다시 쓰면 훨씬 아프니, Q 첫 타 이후 잠시 물러나 두 번째 강화 타격을 헛치게 만드세요.', lv3: '(W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 카밀이 회복하니, W 끝자락을 피해 안쪽으로 붙으세요. (E)\'갈고리 발사\'로 벽을 타고 들어오는 카밀은 착지 시 기절을 거니, 착지 지점에서 벗어난 뒤에 (E)\'포획\'으로 끌어오세요. E가 빠진 카밀을 (W)\'마비의 일격\'으로 둔화시키면 출혈 중첩을 빠르게 채울 수 있어요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 빠져나갈 수 없으니, 카밀의 궁극기 안에서는 (Q)\'학살\' 바깥 날을 노리며 맞받으세요. 출혈 중첩을 가득 쌓고 (R)\'녹서스의 단두대\'로 마무리하면 궁극기 안에서도 싸움을 끝낼 수 있어요. 카밀은 (E)\'갈고리 발사\'로 벽을 넘어 정글러와 함께 들어오니, 라인 옆 벽이 가까운 곳에서는 (E)\'포획\'을 아끼고 시야를 확인하세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'갈고리 발사\'로 빠지는 카밀을 따라가세요. 신발은 카밀의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'전술적 휩쓸기\' 회복을 줄이세요.' },
    '카사딘': { lv1: '카사딘은 (Q)\'무의 구체\'로 견제하지만 함께 얻는 보호막은 마법 피해만 흡수하니 내 물리 피해는 그대로 들어가요. (Q)\'무의 구체\'는 대상에게 발사되는 스킬이라 미니언 뒤로 피하기 어려우니 무리하게 진입하지 말고, (Q)\'학살\'의 도끼날을 챔피언에게 맞혀 체력을 회복하며 버티세요.', lv3: '카사딘의 (E)\'힘의 파동\'이 빠진 타이밍에 (E)\'포획\'으로 끌어당기세요. 이후 (W)\'마비의 일격\'과 (Q)\'학살\'을 빠르게 연계해서 출혈 중첩을 쌓아야 해요.', lv6: '(R)\'균열 이동\'으로 순식간에 거리를 벌리거나 진입하니 이동 스킬이 빠진 뒤에 붙으세요. (E)\'포획\'을 맞힌 뒤 (R)\'녹서스의 단두대\'를 사용해 마무리하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높이고 마법 피해를 흡수하는 보호막으로 생존력을 높여야 해요.', spell: '점멸과 점화예요. 부족한 진입 거리를 보완하고 적의 체력을 깎아 킬각을 잡기 위해 사용해요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\' 견제를 피하며 (Q)\'학살\'로 미니언을 빠르게 정리하세요. 상대의 (E)\'쌍독니\' 공격을 최소화하며 최대한 체력을 보존하는 것이 중요해요. 무리하게 진입하기보다 경험치 획득에 집중하며 거리를 조절해요.', lv3: '(E)\'포획\'으로 상대를 끌어당긴 뒤 (W)\'마비의 일격\'으로 둔화시켜 빠르게 접근하세요. 상대가 (W)\'독기의 늪\'을 깔아 이동을 방해하려 할 때 (Q)\'학살\'의 도끼날 부분을 맞혀 체력을 회복해요. (E)\'쌍독니\'는 중독된 적에게 추가 피해를 입히며 연달아 들어오니 짧게 교환하며 (P)\'과다출혈\' 중첩을 쌓으세요.', lv6: '(W)\'독기의 늪\' 안에 서 있으면 둔화되고 이동 스킬을 쓸 수 없으니 늪 밖으로 먼저 빠져나온 뒤 싸움을 거세요. (R)\'석화의 응시\'는 자신을 바라보는 적을 기절시키니 시전 동작이 보이면 카시오페아를 등지고 움직여 둔화만 받으세요. (E)\'포획\'으로 끌어당겨 (P)\'과다출혈\'을 쌓은 뒤 (R)\'녹서스의 단두대\'로 마무리하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력과 강인함으로 (R)\'석화의 응시\' 지속시간을 줄이고 생명선 보호막으로 생존력을 높이기 위해서예요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 거리를 좁히고 출혈 중첩을 쌓기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 멀리서 견제하며 (P)\'폭풍의 표식\'을 세 번 쌓으면 기절을 걸어요. 표창 직선 밖으로 비켜 서 있다가 빗나간 순간 걸어가 평타를 묻히면 표식 없이 출혈만 쌓는 교환이 돼요. 케넨은 기력을 쓰니 기력이 빠진 뒤에 압박하세요.', lv3: '(E)\'번개 질주\'로 들어오는 케넨은 표식을 남기니, 표식이 두 개 쌓였을 때는 거리를 벌리세요. (E)\'번개 질주\'가 빠진 케넨은 빠르게 빠질 길이 없으니, 이때 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\'까지 이으세요. (W)\'전류 방출\'로 표식을 더 쌓을 수 있으니 W가 빠졌는지 확인하고 들어가세요.', lv6: '(R)\'날카로운 소용돌이\'는 주변 적에게 표식을 쌓으니, 궁극기를 켠 케넨에게 다가가지 마세요. (R)\'날카로운 소용돌이\'가 끝난 케넨이 (E)\'번개 질주\'까지 써 버렸다면 빠질 수단이 없으니, 그때 (E)\'포획\'과 (W)\'마비의 일격\'으로 붙어 (R)\'녹서스의 단두대\'를 꽂으세요. 케넨이 궁극기를 아끼고 있을 때 정글 갱킹이 겹치면 기절이 바로 쌓이니, 강가 시야를 먼저 확보하세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'번개 질주\'로 빠지는 케넨을 따라가세요. 신발은 케넨의 마법 피해와 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'번개 질주\'로 거리를 벌리는 케넨에게 빠르게 붙으세요.' },
    '케일': { lv1: '케일은 초반에 근접 공격이라 (P)\'거룩한 승천\'이 성장하기 전까지 몸싸움이 약해요. 케일이 근접 평타로 막타를 칠 때마다 다가가 평타를 묻혀, (P)\'과다출혈\' 중첩이 꺼지지 않게 유지하세요. 이번 패치에 (Q)\'광휘의 일격\' 재사용 대기시간이 줄었으니 Q 직선을 피하며 압박하세요.', lv3: '(Q)\'광휘의 일격\'에 맞으면 이동 속도와 방어력이 줄어드니, Q가 빠진 뒤에 (E)\'포획\'으로 끌어오세요. (W)\'천상의 축복\'으로 회복하며 빠지는 케일에게 (W)\'마비의 일격\' 둔화를 걸어 붙으세요. (E)\'화염주문검\'은 잃은 체력에 비례해 강해지니 내 체력이 낮을 때는 오래 싸우지 마세요.', lv6: '(R)\'신성한 심판\'은 무적 상태를 만드니, 이번 패치에 재사용 대기시간이 줄어든 만큼 궁극기가 있는지 꼭 확인하세요. 케일이 궁극기를 자신에게 쓰면 무적이 풀리는 자리에 미리 서 있다가, 풀리자마자 (E)\'포획\'으로 끌어와 (R)\'녹서스의 단두대\'까지 이어 주세요. 케일은 (P)\'거룩한 승천\'이 오를수록 사거리가 늘어나 붙기 어려워지니, 라인전 단계에서 포탑을 먼저 깨 두는 게 좋아요.', item: '요우무의 유령검을 첫 코어로 가서 (W)\'천상의 축복\'으로 빠지는 케일을 따라가세요. 신발은 케일의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초반 킬각을 만들어 케일의 성장을 늦추세요.' },
    '코그모': { lv1: '(Q)\'부식성 침\'은 처음 맞은 적에게 맞는 스킬이라 미니언 뒤에 서서 견제를 받아내세요. 거리 조절을 통해 체력 손실을 줄이고 기회를 보며 (Q)\'학살\'로 체력을 회복해요.', lv3: '상대의 (E)\'공허의 분비물\'이 빠진 것을 확인한 뒤 (E)\'포획\'으로 끌어당기세요. 곧바로 (W)\'마비의 일격\'과 (Q)\'학살\'을 연계해 (P)\'과다출혈\' 중첩을 빠르게 쌓아 공격력을 높여요.', lv6: '(R)\'살아있는 곡사포\'에 체력이 많이 깎이지 않게 주의하며 진입하세요. (E)\'포획\'으로 거리를 좁힌 뒤 (R)\'녹서스의 단두대\'로 마무리하고 정글러와 연계해 킬을 내요.', item: '헤르메스의 발걸음과 발걸음 분쇄기를 가요. 마법 저항력으로 마법 피해를 줄이고 둔화 효과를 통해 적을 추격하기 위해서예요.', spell: '점멸과 유체화예요. 유체화의 이동 속도 증가 효과를 이용해 사거리가 긴 적에게 빠르게 접근해야 해요.' },
    '코르키': { lv1: '(Q)\'인광탄\'은 지정한 위치에서 터지는 범위 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 터지는 지역을 벗어나 움직이세요. (W)\'발키리\'의 궤적을 잘 살피며 (Q)\'학살\'의 도끼날을 맞힐 거리를 조절하며 버텨요.', lv3: '(E)\'개틀링 건\'으로 방어력이 깎이기 전에 (E)\'포획\'을 사용하여 거리를 좁히세요. (P)\'과다출혈\' 중첩을 쌓기 위해 (W)\'마비의 일격\'과 평타를 섞어 딜교환을 해요.', lv6: '(R)\'미사일 폭격\'의 폭발 범위에 들어가지 않도록 주의하며 (E)\'포획\'으로 접근하세요. (P)\'과다출혈\'이 쌓였다면 (R)\'녹서스의 단두대\'로 적을 처치하며 킬을 노려요.', item: '헤르메스의 발걸음과 삼위일체를 가요. 마법 저항력을 얻고 공격력과 체력을 높이기 위해서예요.', spell: '점멸과 유체화. 코르키의 긴 사거리를 극복하고 빠르게 접근하기 위해서예요.' },
    '퀸': { lv1: '퀸은 원거리에서 (P)\'매사냥\' 표식을 터뜨리며 평타 견제가 강하고 (E)\'공중제비\'로 거리를 벌려요. 발러가 (P)\'매사냥\' 표식을 남긴 직후 퀸의 첫 평타가 강하니, 표식이 보이면 한 걸음 물러났다가 표식이 터진 뒤에 걸어 들어가 평타를 묻히세요. 1~2레벨 퀸은 근접 거리를 버틸 수단이 (E)\'공중제비\'뿐이라, E를 쓰고 물러난 위치까지 걸어가 다시 압박하세요.', lv3: '(Q)\'실명 공격\'에 맞으면 시야가 좁아지니, 퀸 위치를 놓치지 않게 조심하세요. (E)\'공중제비\'로 퀸이 붙었다가 다시 물러나니, E가 빠진 뒤에 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요. 퀸은 (E)\'공중제비\' 말고는 몸을 빼낼 스킬이 없어서, 끌려온 뒤에는 (Q)\'학살\' 바깥 날까지 그대로 맞아요.', lv6: '퀸이 (R)\'후방 지원\'으로 맵을 돌기 시작하면 퀸 포탑은 비어 있으니 웨이브를 쌓아 포탑을 두드리세요. 퀸은 체력이 낮아 출혈 중첩이 쌓이면 (R)\'녹서스의 단두대\' 한 번으로 끝나는 경우가 많아요. 퀸은 (W)\'예리한 감각\'으로 주변을 드러낼 수 있으니 수풀에서 기다리는 매복은 잘 통하지 않아요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'공중제비\'로 빠지는 퀸을 따라가세요. 신발은 퀸의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 원거리 견제를 이겨내며 퀸에게 붙으세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 견제하며 둔화를 걸고, 두 번 쌓이면 충격파로 끌어당겨요. 크산테가 (Q)\'엔토포 타격\' 첫 타를 미니언에 쓰는 순간 앞으로 걸어가 평타로 (P)\'과다출혈\'을 묻히고, 두 번째 중첩 충격파가 오기 전에 물러나세요. 1~2레벨 크산테는 (E)\'발놀림\' 보호막 말고는 버틸 수단이 적으니 웨이브를 크산테 포탑 쪽으로 몰아 두고 견제를 이어 가세요.', lv3: '(W)\'길을 여는 자\'로 충전하는 크산테는 받는 피해가 줄고 돌진하며 기절을 거니, W를 충전하는 동안은 (E)\'포획\'을 아껴 두세요. (E)\'발놀림\'으로 보호막을 얻으며 돌진하는 크산테에게 보호막이 끝난 뒤에 (Q)\'학살\' 바깥 날을 맞히세요. W가 빠진 크산테를 (E)\'포획\'으로 끌어와 출혈 중첩을 채우세요.', lv6: '(R)\'총공세\'를 쓴 크산테는 방어력이 줄어드는 대신 피해가 늘어나니, 궁극기 시간에 출혈 중첩을 가득 쌓아 (R)\'녹서스의 단두대\'를 노리세요. 크산테의 궁극기로 벽 너머로 밀려나면 상대 정글러에게 잡힐 수 있으니 시야를 확인하세요. (R)\'총공세\'가 없는 크산테는 처형선까지 깎기 어려우니, 궁극기가 빠진 동안 웨이브를 크게 밀어 넣고 포탑을 두드리세요.', item: '단단한 크산테에게는 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 방어력을 주고 크산테의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테는 처치가 어려우니 순간이동으로 라인 손해를 줄이세요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 붙잡아 끌어당기며 1~2레벨 몸싸움이 강해요. 덫에 맞은 채 클레드 근처에 머물면 끌려가니, 맞자마자 클레드에게서 멀어지세요. 클레드가 (Q)\'덫날리기\'를 빗맞혔다면 바로 걸어 들어가 평타와 (W)\'마비의 일격\'으로 출혈을 남기세요.', lv3: '(E)\'이랴!\'로 돌진했다가 다시 돌진하는 클레드에게 착지 지점에서 (Q)\'학살\' 바깥 날을 맞히세요. (W)\'버럭버럭\'으로 공격 속도가 오른 클레드와 오래 평타 싸움을 하지 마세요. 스칼에서 내린 클레드는 피해가 줄어드니 그때 (E)\'포획\'으로 끌어와 출혈 중첩을 채우세요.', lv6: '(R)\'돌겨어어억!!!\'으로 멀리서 돌진하는 클레드는 정글러와 함께 다이브하니, 라인을 당겨 받으세요. 스칼에서 내린 클레드는 원거리 사격을 쏠 때마다 뒤로 밀려나며 용기를 채우니, 밀려나는 방향으로 (E)\'포획\'을 던져 끌어오고 (R)\'녹서스의 단두대\'까지 이으세요. 클레드가 스칼을 다시 타기 전에 끝내는 게 중요해요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'이랴!\'로 빠지는 클레드를 따라가세요. 신발은 클레드의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 스칼을 다시 타기 전에 클레드를 처치하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 체력을 회복해요. (Q)\'혀 채찍\'은 처음 맞은 유닛에게 닿으므로 미니언 뒤에 서서 막아내세요. (P)\'절대 미각\' 중첩이 쌓이기 전에 (W)\'마비의 일격\'으로 둔화시키고 짧게 교환하세요.', lv3: '(W)\'심연 잠수\'는 지정한 장소의 적을 공중으로 띄워 스킬을 쓸 수 없게 하니, 착지 지점에서 미리 벗어나세요. (W)\'심연 잠수\'가 빠진 뒤에 (E)\'포획\'으로 끌어당겨 (Q)\'학살\'의 도끼날로 체력을 회복하세요. (E)\'두꺼운 피부\'는 비축한 피해를 보호막으로 바꾸니 보호막이 사라진 뒤에 공격하세요.', lv6: '(P)\'절대 미각\' 중첩이 세 번 쌓이면 (R)\'집어삼키기\'에 먹힐 수 있으니 주의하세요. (Q)\'학살\'과 (W)\'마비의 일격\'으로 출혈 중첩을 빠르게 쌓은 뒤 (R)\'녹서스의 단두대\'로 마무리하세요. 탐 켄치가 (W)\'심연 잠수\'로 아군을 구하러 올 때를 대비해 라인 관리를 철저히 하세요.', item: '첫 코어 아이템은 칠흑의 양날 도끼를 가서 탐 켄치를 상대로 방어력을 깎으세요. 신발은 마법 피해를 줄이고 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 탐 켄치가 (Q)\'혀 채찍\'으로 체력을 회복하므로 점화의 치유 감소 효과가 매우 중요해요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 1~2레벨 평타 교환이 강해요. (Q)\'깨물기\'를 맞은 뒤에는 공격력이 줄어드니 오래 평타 싸움을 하지 말고 평타로 (P)\'과다출혈\'만 묻히고 빠지세요. 트런들은 (P)\'헌납\'으로 주변 유닛이 쓰러질 때 회복하니 미니언이 많은 곳에서 싸우지 마세요.', lv3: '(W)\'얼음 왕국\' 안에서 트런들은 공격 속도와 이동 속도가 오르니, W 영역 밖으로 빠지세요. (E)\'얼음 기둥\'에 막히면 거리를 좁히기 어려우니 E가 빠진 뒤에 (E)\'포획\'으로 끌어오세요. W 밖으로 끌어낸 트런들에게 (Q)\'학살\' 바깥 날을 맞히세요.', lv6: '(R)\'진압\'은 체력과 방어력을 훔치니, 트런들이 궁극기를 쓰면 바로 빠지세요. (R)\'진압\'으로 훔친 능력치가 사라질 때까지 기다렸다가, 원래 방어력으로 돌아온 트런들에게 (E)\'포획\'의 방어력 무시를 살려 중첩을 채우세요. (E)\'얼음 기둥\'으로 도망길을 막고 정글러가 합류하는 갱킹이 잦으니, 체력이 낮을 때는 기둥이 놓이기 좋은 좁은 길목을 피하세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'얼음 기둥\'을 돌아 트런들을 따라가세요. 신발은 트런들의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'헌납\' 회복을 줄이세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 모으고 (Q)\'피의 갈망\'으로 체력을 회복해요. 트린다미어가 (E)\'회전 베기\'를 막타에 쓰고 나면 거리를 벌릴 수단이 없으니, 그 직후 붙어서 평타로 (P)\'과다출혈\'을 쌓으세요. 웨이브를 트린다미어 포탑 쪽으로 밀어 두면 막타로 분노를 쌓기 어려워져요.', lv3: '(W)\'조롱의 외침\'은 공격력을 낮추고 등을 돌리면 둔화시키니, W를 맞으면 등을 돌리지 말고 맞받으세요. (E)\'회전 베기\'로 들어오는 트린다미어에게 착지 지점에서 (Q)\'학살\' 바깥 날을 맞히세요. E가 빠진 트린다미어를 (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요.', lv6: '(R)\'불사의 분노\'를 쓴 트린다미어는 죽지 않으니, 궁극기 시간 동안 (R)\'녹서스의 단두대\'를 아껴 두세요. (R)\'불사의 분노\' 동안 평타와 (Q)\'학살\'로 출혈을 가득 채워 두면, 지속시간이 끝나는 순간 쓰는 (R)\'녹서스의 단두대\'로 바로 처형할 수 있어요. 다만 내 체력이 낮다면 출혈을 채우려 붙어 있지 말고 거리를 벌려 지속시간을 버티세요.', item: '요우무의 유령검을 첫 코어로 가서 (E)\'회전 베기\'로 빠지는 트린다미어를 따라가세요. 신발은 트린다미어의 치명타 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'피의 갈망\' 회복을 줄이세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 평타마다 독을 쌓고 (Q)\'실명 다트\'로 평타를 막아서 근접 챔피언을 괴롭혀요. 실명에 걸리면 평타가 빗나가니 그때는 (Q)\'학살\'로 피해를 넣거나 빠지세요. 실명이 풀리면 곧장 티모 쪽으로 걸어가 평타를 묻혀 출혈을 다시 쌓으세요.', lv3: '(W)\'신속한 이동\'으로 티모가 빠르게 도망치니, (E)\'포획\'으로 끌어와 (W)\'마비의 일격\' 둔화를 거세요. (Q)\'실명 다트\'가 빠진 걸 확인하고 들어가는 게 가장 확실해요. 티모가 수풀에 들어가 (P)\'유격 전투\'로 투명해지면 무리하게 쫓지 마세요.', lv6: '(R)\'유독성 함정\' 버섯은 밟으면 둔화와 피해를 주니, 라인과 수풀 길목에 깔린 버섯을 피해 다니세요. 티모는 체력이 낮아 출혈 중첩이 쌓이면 (R)\'녹서스의 단두대\'로 끝낼 수 있으니 투명해지기 전에 쓰세요. 티모가 라인을 비우면 수풀마다 버섯을 깔러 간 경우가 많으니 그 사이 웨이브를 밀어 포탑을 두드리세요.', item: '요우무의 유령검을 첫 코어로 가서 (W)\'신속한 이동\'으로 빠지는 티모를 따라가세요. 신발은 (E)\'맹독 다트\' 독 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (W)\'신속한 이동\' 티모를 따라잡을 수 있어요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 멀리서 견제하며 1~2레벨 피해가 강해요. (Q)\'혜성의 창\'을 던진 직후의 판테온에게 걸어 들어가 평타 두 번으로 출혈을 남기고 다시 빠지세요. (P)\'필멸자의 의지\'가 다 쌓이면 다음 스킬이 강화되니, 그때는 교환을 피하고 강화 스킬을 뺀 뒤에 들어가세요.', lv3: '(W)\'방호의 도약\'에 기절되면 (Q)\'학살\'을 바깥 날로 맞히기 어려우니, W가 빠진 뒤에 (E)\'포획\'으로 끌어오세요. (E)\'방패 돌격\' 동안 판테온은 정면 공격에 무적이니, E가 켜진 동안은 평타를 치지 말고 옆으로 돌아가세요. 스킬이 빠진 판테온에게 (W)\'마비의 일격\' 둔화를 걸어 출혈 중첩을 채우세요.', lv6: '판테온은 (W)\'방호의 도약\' 기절로 묶은 뒤 정글러와 마무리하는 갱킹이 잦으니, W가 남아 있을 때는 라인을 깊게 밀지 마세요. (E)\'방패 돌격\'이 끝난 판테온에게 출혈을 가득 채운 뒤 (R)\'녹서스의 단두대\'를 쓰세요. 판테온이 (R)\'거대 유성\'을 들고 사라지면 다른 라인 합류 신호이니 바로 핑을 찍고 웨이브를 포탑에 밀어 넣으세요.', item: '요우무의 유령검을 첫 코어로 가서 (Q)\'혜성의 창\' 사거리 밖에서 빠르게 붙으세요. 신발은 판테온의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 초반 킬각을 만들어 판테온의 압박을 끊으세요.' },
    '피들스틱': { lv1: '1~2레벨에는 피들스틱의 (Q)\'공포\' 사거리에 노출되지 않도록 거리 조절을 하며 미니언을 챙기세요. (Q)\'학살\'의 도끼날 부분을 맞춰서 체력을 회복하고 (P)\'과다출혈\' 중첩을 차근차근 쌓는 것이 중요해요.', lv3: '(E)\'수확\'은 범위 중심에 있으면 침묵에 걸려 스킬을 쓸 수 없으니, 맞기 전에 (E)\'포획\'으로 끌어당기세요. (W)\'마비의 일격\'으로 적을 둔화시키며 (P)\'과다출혈\' 중첩을 쌓으면 딜교환을 이끌 수 있어요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'을 사용하며 넓은 범위로 피해를 입힐 때 위치 선정에 신중해야 해요. (P)\'과다출혈\' 중첩이 쌓였다면 (R)\'녹서스의 단두대\'를 사용하여 피들스틱을 확실하게 처치하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 선택해요. 피들스틱의 마법 피해를 견디고 생명선 효과로 버티기 위해서예요.', spell: '점멸과 점화. 피들스틱의 체력이 낮을 때 점화로 추가 피해를 주어 확실하게 처치해요.' },
    '피오라': { lv1: '피오라는 (P)\'치명적인 검무\'로 급소를 드러내 가격하면 회복하고 이동 속도가 올라요. 1~2레벨에는 급소 방향을 피해 서고, 피오라가 (Q)\'찌르기\'로 들어오면 평타로 (P)\'과다출혈\'을 맞받으세요. 피오라는 짧게 교환하고 빠지니 출혈을 남기고 쫓지 마세요.', lv3: '(W)\'응수\'는 공격과 이동 불가 효과를 막아내고, 이동 불가 효과를 막으면 기절을 거니 W가 켜진 동안은 (E)\'포획\'과 (W)\'마비의 일격\'을 쓰지 마세요. (W)\'응수\'가 빠진 뒤에 (E)\'포획\'으로 끌어와 (Q)\'학살\' 바깥 날을 맞히세요. (E)\'대가의 검술\'로 강화 평타를 치는 피오라와 오래 평타 싸움을 하지 마세요.', lv6: '(R)\'대결투\'를 쓴 피오라는 급소 네 군데를 모두 가격하면 회복하니, 급소 방향을 계속 바꾸며 피하세요. 출혈 중첩을 가득 쌓은 피오라에게 (W)\'응수\'가 빠졌을 때 (R)\'녹서스의 단두대\'로 마무리하세요. 피오라는 혼자 사이드를 미는 힘이 갈수록 강해지니, 라인전에서 포탑을 먼저 깨고 웨이브 주도권을 가져오세요.', item: '요우무의 유령검을 첫 코어로 가서 (Q)\'찌르기\'로 빠지는 피오라를 따라가세요. 신발은 피오라의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'치명적인 검무\' 회복을 줄이세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 지키며, 포탑 근처에서 이동 속도가 올라요. 1~2레벨에는 포탑 사거리 밖에서 막타를 챙기고, 하이머딩거가 막타를 치러 다가올 때 평타로 (P)\'과다출혈\'을 묻히세요. 포탑을 평타로 부수면 하이머딩거의 라인 장악력이 크게 줄어요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'에 직격당하면 기절하니, E가 빠진 뒤에 (E)\'포획\'으로 끌어오세요. (W)\'마법공학 초소형 로켓\'은 마우스 위치로 모이니 하이머딩거 정면에 서지 마세요. (Q)\'학살\' 바깥 날로 포탑과 하이머딩거를 같이 맞히면 회복까지 챙길 수 있어요.', lv6: '(R)\'업그레이드!!!\'로 강화된 스킬은 피해가 크니, 하이머딩거가 궁극기를 쓴 뒤에 들어가세요. 포탑을 다 잃은 하이머딩거는 몸을 지킬 수단이 (E)\'CH-2 전자폭풍 수류탄\' 하나뿐이라, E가 빠지면 출혈을 채워 (R)\'녹서스의 단두대\'로 끝낼 수 있어요. 포탑이 여럿 모인 자리에는 들어가지 말고, 하이머딩거가 포탑을 새로 깔러 앞으로 나올 때를 노리세요.', item: '요우무의 유령검의 이동 속도로 포탑 사거리를 빠르게 지나 하이머딩거 본체에 붙으세요. 신발은 하이머딩거의 마법 피해와 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 포탑 사거리를 빠르게 빠져나가세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_darius);
if (typeof module !== 'undefined') module.exports = top_darius;
